INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0927dd39-7dea-5f4c-b2d1-57e4654ee9eb', id, 'fazilat-laylatul-qadr', '{"bn": "লাইলাতুল কদরের ফজিলত", "en": "Virtues of Laylat al-Qadr"}', '{"bn": "হাজার মাসের চেয়ে উত্তম এক রাত; রমজানের শেষ দশকের বেজোড় রাতে খুঁজতে হয়, আর রাসুল ﷺ শিখিয়েছেন বিশেষ দোয়া।", "en": "A night better than a thousand months; seek it in the odd nights of the last ten of Ramadan, with the special dua the Prophet ﷺ taught."}', 'basic', '[{"type": "arabic", "ar": "لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ", "pron": {"bn": "লাইলাতুল কাদরি খাইরুম মিন আলফি শাহর", "en": "Laylatul-qadri khayrum min alfi shahr"}, "meaning": {"bn": "কদরের রাত হাজার মাসের চেয়ে উত্তম।", "en": "The Night of Decree is better than a thousand months."}, "ref": {"bn": "সূরা কদর ৯৭:৩", "en": "Al-Qadr 97:3"}}, {"type": "text", "text": {"bn": "এই রাতে কুরআন নাজিল হয়েছে; এ রাতে ফেরেশতা ও জিবরিল (আ.) রবের অনুমতিতে নেমে আসেন, আর ফজর পর্যন্ত শান্তি থাকে। আল্লাহ আরও বলেন: “এ রাতে প্রতিটি প্রজ্ঞাপূর্ণ বিষয়ের ফয়সালা করা হয়।”", "en": "The Quran was revealed in this night; angels and Jibril descend by their Lord''s permission, and it is peace until dawn. Allah also says: “In it every wise matter is made distinct.”"}}, {"type": "ref", "text": {"bn": "সূরা কদর ৯৭:১–৫; সূরা দুখান ৪৪:৩–৪", "en": "Al-Qadr 97:1–5; Ad-Dukhan 44:3–4"}}, {"type": "text", "text": {"bn": "যে ঈমানের সঙ্গে ও সওয়াবের আশায় লাইলাতুল কদরে নামাজে দাঁড়ায়, তার আগের গুনাহ মাফ করে দেওয়া হয়।", "en": "Whoever stands in prayer on Laylat al-Qadr out of faith and hoping for reward, his previous sins are forgiven."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০১; সহিহ মুসলিম ৭৬০", "en": "Sahih al-Bukhari 1901; Sahih Muslim 760"}}, {"type": "text", "text": {"bn": "রমজানের শেষ দশ দিন শুরু হলে রাসুল ﷺ কোমর বেঁধে নিতেন, রাত জেগে ইবাদত করতেন এবং পরিবারকেও জাগাতেন। তিনি এই দশ দিনে অন্য সময়ের চেয়ে বেশি পরিশ্রম করতেন।", "en": "When the last ten days began, the Prophet ﷺ tightened his waist-wrap, spent the nights in worship and woke his family; he strove in them more than at any other time."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০২৪; সহিহ মুসলিম ১১৭৫", "en": "Sahih al-Bukhari 2024; Sahih Muslim 1175"}}, {"type": "differ", "title": {"bn": "কোন রাত লাইলাতুল কদর", "en": "Which night is Laylat al-Qadr"}, "views": [{"label": {"bn": "শেষ দশকের যেকোনো বেজোড় রাত", "en": "Any odd night of the last ten"}, "text": {"bn": "রাতটি নির্দিষ্ট করে জানানো হয়নি; শেষ দশকের বেজোড় রাতগুলোতে (২১, ২৩, ২৫, ২৭, ২৯) খুঁজতে হবে, এবং অনেক আলেমের মতে এটি বছরে বছরে পরিবর্তন হতে পারে।", "en": "The night was not fixed for us; seek it in the odd nights of the last ten (21, 23, 25, 27, 29), and many scholars hold it may move from year to year."}, "evidence": {"bn": "“রমজানের শেষ দশকের বেজোড় রাতে লাইলাতুল কদর খোঁজো” (সহিহ বুখারি ২০১৭)।", "en": "“Seek Laylat al-Qadr in the odd nights of the last ten of Ramadan” (Sahih al-Bukhari 2017)."}}, {"label": {"bn": "২৭তম রাতের সম্ভাবনা সবচেয়ে বেশি", "en": "The 27th is the most likely"}, "text": {"bn": "সাহাবি উবাই ইবনে কা''ব (রা.) কসম করে বলতেন এটি ২৭তম রাত; উপমহাদেশে হানাফিসহ অনেকেই এ রাতকে বিশেষ গুরুত্ব দেন, তবে অন্য রাতগুলোও ছাড়েন না।", "en": "Ubayy ibn Ka''b (RA) used to swear it was the 27th; many in the subcontinent, including Hanafis, give that night special weight without neglecting the others."}, "evidence": {"bn": "উবাই ইবনে কা''ব (রা.)-এর বর্ণনা (সহিহ মুসলিম ৭৬২)।", "en": "The narration of Ubayy ibn Ka''b (Sahih Muslim 762)."}}]}, {"type": "heading", "text": {"bn": "লাইলাতুল কদরের দোয়া", "en": "The dua for Laylat al-Qadr"}}, {"type": "arabic", "label": {"bn": "আয়েশা (রা.)-কে শেখানো দোয়া", "en": "The dua taught to Aishah (RA)"}, "ar": "اللّٰهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "pron": {"bn": "আল্লাহুম্মা ইন্নাকা আফুউউন তুহিব্বুল আফওয়া ফা''ফু আন্নী", "en": "Allahumma innaka ''afuwwun tuhibbul-''afwa fa''fu ''anni"}, "meaning": {"bn": "হে আল্লাহ, আপনি ক্ষমাশীল, ক্ষমা করতে ভালোবাসেন; সুতরাং আমাকে ক্ষমা করুন।", "en": "O Allah, You are Pardoning and love to pardon, so pardon me."}, "ref": {"bn": "সুনান তিরমিজি ৩৫১৩; সুনান ইবনে মাজাহ ৩৮৫০", "en": "Jami'' at-Tirmidhi 3513; Sunan Ibn Majah 3850"}}, {"type": "note", "tone": "info", "text": {"bn": "কিছু ছাপায় এই দোয়ায় “কারীম” শব্দ যুক্ত আছে; অনেক মুহাদ্দিস উল্লেখ করেছেন যে নির্ভরযোগ্য বর্ণনায় শব্দটি নেই।", "en": "Some prints add “karim” to this dua; many hadith scholars note that the reliable narrations do not contain it."}}, {"type": "note", "tone": "tip", "text": {"bn": "শেষ দশকের প্রতিটি রাতে অন্তত কিছু নামাজ, কুরআন, দোয়া ও ইস্তিগফার করুন, তাহলে যে রাতেই হোক আপনি তা পাবেন ইনশাআল্লাহ।", "en": "Spend every night of the last ten with some prayer, Quran, dua and istighfar, so you catch it whichever night it is, in sha Allah."}}]', 'in_review', 200 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '580c6d4d-8962-57da-899f-293addd4dc85', id, 'fazilat-nafl-sawm', '{"bn": "নফল রোজার ফজিলত: আরাফা, আশুরা, শাওয়াল ও অন্যান্য", "en": "Voluntary fasts: Arafah, Ashura, Shawwal and more"}', '{"bn": "আরাফার রোজা দুই বছরের, আশুরার রোজা এক বছরের গুনাহের কাফফারা; শাওয়ালের ছয় রোজায় সারা বছরের সওয়াব।", "en": "Fasting Arafah expiates two years and Ashura one year; six days of Shawwal bring the reward of a whole year."}', 'detail', '[{"type": "text", "text": {"bn": "আল্লাহর পথে (আল্লাহর সন্তুষ্টির জন্য) একদিন রোজা রাখলে আল্লাহ তার চেহারাকে জাহান্নাম থেকে সত্তর বছরের দূরত্বে সরিয়ে দেন।", "en": "Whoever fasts one day for the sake of Allah, Allah keeps his face seventy years'' distance from the Fire."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৮৪০; সহিহ মুসলিম ১১৫৩", "en": "Sahih al-Bukhari 2840; Sahih Muslim 1153"}}, {"type": "table", "head": [{"bn": "রোজা", "en": "Fast"}, {"bn": "ফজিলত", "en": "Virtue"}, {"bn": "সূত্র", "en": "Source"}], "rows": [[{"bn": "আরাফার দিন (৯ জিলহজ)", "en": "Day of Arafah (9 Dhul-Hijjah)"}, {"bn": "আগের ও পরের এক বছরের গুনাহের কাফফারা আশা করা যায়", "en": "Hoped to expiate the year before and the year after"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}], [{"bn": "আশুরা (১০ মহররম)", "en": "Ashura (10 Muharram)"}, {"bn": "আগের এক বছরের গুনাহের কাফফারা আশা করা যায়", "en": "Hoped to expiate the previous year"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}], [{"bn": "শাওয়ালের ছয় রোজা", "en": "Six days of Shawwal"}, {"bn": "রমজানের সঙ্গে মিলে সারা বছর রোজার সমান", "en": "With Ramadan, like fasting the whole year"}, {"bn": "সহিহ মুসলিম ১১৬৪", "en": "Sahih Muslim 1164"}], [{"bn": "মহররম মাস", "en": "The month of Muharram"}, {"bn": "রমজানের পর শ্রেষ্ঠ রোজা", "en": "The best fasting after Ramadan"}, {"bn": "সহিহ মুসলিম ১১৬৩", "en": "Sahih Muslim 1163"}], [{"bn": "সোমবার", "en": "Monday"}, {"bn": "রাসুল ﷺ-এর জন্মদিন ও ওহি নাজিলের দিন", "en": "The day the Prophet ﷺ was born and revelation began"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}]]}, {"type": "note", "tone": "info", "text": {"bn": "আরাফার রোজা হজে না যাওয়া লোকদের জন্য; আরাফার ময়দানে থাকা হাজিদের জন্য রোজা না রাখাই সুন্নত।", "en": "The Arafah fast is for those not on hajj; for pilgrims standing at Arafah, the sunnah is not to fast."}}, {"type": "heading", "text": {"bn": "আশুরার সঙ্গে ৯ তারিখ", "en": "Adding the 9th to Ashura"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছিলেন: আগামী বছর বেঁচে থাকলে আমি অবশ্যই ৯ তারিখেও রোজা রাখব। তাই আলেমরা ১০ তারিখের সঙ্গে ৯ তারিখ (না পারলে ১১ তারিখ) মিলিয়ে রোজা রাখতে উৎসাহ দেন; হানাফি আলেমরা শুধু ১০ তারিখ একা রাখাকে অনুত্তম বলেছেন।", "en": "The Prophet ﷺ said: if I live until next year I will fast the 9th as well. So scholars encourage adding the 9th (or else the 11th) to the 10th; Hanafi scholars consider fasting the 10th alone less preferable."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৩৪", "en": "Sahih Muslim 1134"}}, {"type": "heading", "text": {"bn": "প্রতি মাসের রোজা", "en": "Monthly fasts"}}, {"type": "list", "items": [{"bn": "প্রতি মাসে তিন দিন রোজা রাখা সারা বছর রোজা রাখার মতো; আবু হুরাইরা (রা.)-কে রাসুল ﷺ এর অসিয়ত করেছিলেন (সহিহ বুখারি, সহিহ মুসলিম)।", "en": "Fasting three days every month is like fasting all year; the Prophet ﷺ advised Abu Hurairah (RA) with it (al-Bukhari, Muslim)."}, {"bn": "সোমবার ও বৃহস্পতিবার আমল আল্লাহর কাছে পেশ করা হয়, তাই রাসুল ﷺ এ দুই দিন রোজা রাখতে পছন্দ করতেন (সুনান তিরমিজি)।", "en": "Deeds are presented to Allah on Mondays and Thursdays, so the Prophet ﷺ liked to fast on them (Jami'' at-Tirmidhi)."}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "শাওয়ালের ছয় রোজা ঈদের পর একটানা বা আলাদা আলাদা যেকোনোভাবে রাখা যায়; কারও রমজানের কাজা থাকলে আগে কাজা আদায় করা উত্তম।", "en": "The six Shawwal fasts may be kept consecutively or separately after Eid; whoever owes Ramadan days should preferably make them up first."}}]', 'in_review', 210 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '1c0323c1-35a4-59a5-954b-db64d917ac3d', id, 'fazilat-dhul-hijjah', '{"bn": "জিলহজের প্রথম দশ দিনের ফজিলত", "en": "Virtues of the first ten days of Dhul-Hijjah"}', '{"bn": "বছরের শ্রেষ্ঠ দিনগুলো: এ সময়ের নেক আমল আল্লাহর কাছে সবচেয়ে প্রিয়; আরাফার রোজা, তাকবির ও কুরবানি।", "en": "The best days of the year: good deeds in them are most beloved to Allah; the Arafah fast, takbir and sacrifice."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ কসম করে বলেছেন: “শপথ ফজরের, শপথ দশ রাতের।” অধিকাংশ মুফাসসিরের মতে এই দশ রাত জিলহজের প্রথম দশক।", "en": "Allah swears: “By the dawn, and by the ten nights.” Most commentators say these are the first ten of Dhul-Hijjah."}}, {"type": "ref", "text": {"bn": "সূরা ফাজর ৮৯:১–২", "en": "Al-Fajr 89:1–2"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: এমন কোনো দিন নেই যেদিনের নেক আমল আল্লাহর কাছে এই দশ দিনের আমলের চেয়ে বেশি প্রিয়। সাহাবিরা বললেন, আল্লাহর পথে জিহাদও নয়? তিনি বললেন: জিহাদও নয়; তবে সেই ব্যক্তি ছাড়া, যে জান-মাল নিয়ে বের হয়ে আর কিছু নিয়েই ফেরেনি।", "en": "There are no days in which righteous deeds are more beloved to Allah than these ten. They asked: not even jihad? He said: not even jihad, except a man who went out with his life and wealth and returned with nothing."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৬৯; সুনান আবু দাউদ ২৪৩৮", "en": "Sahih al-Bukhari 969; Sunan Abi Dawud 2438"}}, {"type": "heading", "text": {"bn": "এই দিনগুলোর আমল", "en": "Deeds in these days"}}, {"type": "list", "items": [{"bn": "বেশি বেশি তাকবির, তাহলিল ও তাহমিদ পড়া; সাহাবি ইবনে উমর ও আবু হুরাইরা (রা.) এই দিনগুলোতে বাজারে গিয়ে তাকবির বলতেন, আর মানুষও তাঁদের সঙ্গে বলত (সহিহ বুখারি, ঈদ অধ্যায়)।", "en": "Abundant takbir, tahlil and praise; Ibn Umar and Abu Hurairah (RA) would go to the market in these days saying takbir and people would join them (al-Bukhari, Book of the Eids)."}, {"bn": "৯ তারিখ আরাফার রোজা, যা আগের ও পরের এক বছরের গুনাহের কাফফারা আশা করা যায় (সহিহ মুসলিম ১১৬২)।", "en": "Fasting on the 9th, the Day of Arafah, hoped to expiate the year before and after (Sahih Muslim 1162)."}, {"bn": "আরাফার দিনের মতো আর কোনো দিন আল্লাহ এত বান্দাকে জাহান্নাম থেকে মুক্তি দেন না (সহিহ মুসলিম ১৩৪৮)।", "en": "There is no day on which Allah frees more servants from the Fire than the Day of Arafah (Sahih Muslim 1348)."}, {"bn": "সামর্থ্য থাকলে ঈদের দিন কুরবানি করা।", "en": "Offering the sacrifice on Eid if able."}, {"bn": "নামাজ, কুরআন, সদকা, তওবা ইত্যাদি সব নেক আমল বাড়িয়ে দেওয়া।", "en": "Increasing all good deeds: prayer, Quran, charity and repentance."}]}, {"type": "arabic", "label": {"bn": "তাকবির (সাহাবিদের থেকে বর্ণিত শব্দ)", "en": "Takbir (wording reported from the Companions)"}, "ar": "اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، وَلِلّٰهِ الْحَمْدُ", "pron": {"bn": "আল্লাহু আকবার, আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু ওয়াল্লাহু আকবার, আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ", "en": "Allahu akbar, Allahu akbar, la ilaha illallahu wallahu akbar, Allahu akbar, wa lillahil-hamd"}, "meaning": {"bn": "আল্লাহ সর্বশ্রেষ্ঠ, আল্লাহ সর্বশ্রেষ্ঠ; আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই; আল্লাহ সর্বশ্রেষ্ঠ, আল্লাহ সর্বশ্রেষ্ঠ, আর সব প্রশংসা আল্লাহর।", "en": "Allah is the Greatest, Allah is the Greatest; there is no god but Allah; Allah is the Greatest, Allah is the Greatest, and to Allah belongs all praise."}, "ref": {"bn": "মুসান্নাফ ইবনে আবি শাইবা", "en": "Musannaf Ibn Abi Shaybah"}, "check": true}, {"type": "heading", "text": {"bn": "কুরবানিদাতার চুল-নখ না কাটা", "en": "The sacrificer not cutting hair and nails"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: জিলহজের দশ দিন শুরু হলে তোমাদের কেউ কুরবানি করার ইচ্ছা করলে সে যেন (কুরবানি পর্যন্ত) চুল ও নখ না কাটে।", "en": "When the ten days begin and one of you intends to sacrifice, let him not cut his hair or nails (until he sacrifices)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৭৭", "en": "Sahih Muslim 1977"}}, {"type": "differ", "title": {"bn": "এই নির্দেশের হুকুম", "en": "Ruling of this instruction"}, "views": [{"label": {"bn": "হানাফি, মালিকি ও শাফেয়ি", "en": "Hanafi, Maliki and Shafi''i"}, "text": {"bn": "মুস্তাহাব; কাটলে গুনাহ নেই, তবে না কাটা উত্তম।", "en": "Recommended; cutting is not sinful, but refraining is better."}, "evidence": {"bn": "আয়েশা (রা.)-এর বর্ণনা: রাসুল ﷺ মদিনা থেকে কুরবানির পশু পাঠাতেন, অথচ ইহরামকারীর জন্য যা নিষিদ্ধ তার কিছুই নিজের ওপর হারাম করতেন না (সহিহ বুখারি, সহিহ মুসলিম); তাই তাঁরা নির্দেশটিকে উৎসাহমূলক বুঝেছেন।", "en": "Aishah''s narration that the Prophet ﷺ sent sacrificial animals from Madinah without abstaining from anything forbidden to a pilgrim (al-Bukhari, Muslim); so they read the instruction as encouragement."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "ওয়াজিব; কুরবানির আগে কাটা হারাম, তবে কুরবানি সহিহ হবে।", "en": "Obligatory; cutting before the sacrifice is forbidden, though the sacrifice remains valid."}, "evidence": {"bn": "সহিহ মুসলিমের নির্দেশটি সরাসরি নিষেধবাচক শব্দে এসেছে।", "en": "The instruction in Sahih Muslim is a direct prohibition."}}], "check": true}]', 'in_review', 220 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'deb3fef6-a819-5275-ab05-0b40d20ed582', id, 'fazilat-shab-e-barat', '{"bn": "শবে বরাত (১৫ শাবান): বর্ণনা ও আলেমদের মত", "en": "Shab-e-Barat (15 Sha''ban): narrations and scholarly views"}', '{"bn": "মধ্য শাবানের রাত সম্পর্কে বর্ণিত হাদিসগুলোর মান, আলেমদের দুটি প্রধান মত এবং যেসব বিষয়ে সবাই একমত।", "en": "The grading of the narrations about the night of mid-Sha''ban, the two main scholarly views, and what all agree on."}', 'detail', '[{"type": "text", "text": {"bn": "শাবান মাস নিজেই ফজিলতপূর্ণ: আয়েশা (রা.) বলেন, রমজান ছাড়া অন্য কোনো মাসে রাসুল ﷺ-কে শাবানের চেয়ে বেশি রোজা রাখতে দেখিনি।", "en": "Sha''ban itself is virtuous: Aishah (RA) said she never saw the Prophet ﷺ fast more in any month besides Ramadan than in Sha''ban."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৬৯; সহিহ মুসলিম ১১৫৬", "en": "Sahih al-Bukhari 1969; Sahih Muslim 1156"}}, {"type": "text", "text": {"bn": "উসামা ইবনে যায়েদ (রা.)-এর বর্ণনায় রাসুল ﷺ বলেছেন, শাবান এমন মাস যার ব্যাপারে মানুষ উদাসীন থাকে, আর এ মাসে আমল রব্বুল আলামিনের কাছে তুলে ধরা হয়।", "en": "In the narration of Usamah ibn Zayd (RA), the Prophet ﷺ said Sha''ban is a month people neglect, and in it deeds are raised to the Lord of the worlds."}}, {"type": "ref", "text": {"bn": "সুনান নাসায়ি", "en": "Sunan an-Nasa''i"}, "check": true}, {"type": "heading", "text": {"bn": "মধ্য শাবানের রাত সম্পর্কে বর্ণনা", "en": "Narrations about the night of mid-Sha''ban"}}, {"type": "list", "items": [{"bn": "“আল্লাহ মধ্য শাবানের রাতে সৃষ্টির দিকে দৃষ্টি দেন এবং মুশরিক ও বিদ্বেষ পোষণকারী ছাড়া সবাইকে ক্ষমা করেন।” এটি সুনান ইবনে মাজাহ (১৩৯০), সহিহ ইবনে হিব্বান ইত্যাদিতে কয়েকজন সাহাবি থেকে এসেছে। প্রতিটি সনদে দুর্বলতা আছে; তবে সব সূত্র মিলিয়ে অনেক মুহাদ্দিস (যেমন আলবানি) একে সহিহ/হাসান বলেছেন, আর অন্যরা দুর্বলই মনে করেন।", "en": "“Allah looks at His creation on the night of mid-Sha''ban and forgives all except a polytheist or one harbouring hatred.” Reported from several Companions in Sunan Ibn Majah (1390), Sahih Ibn Hibban and others. Each chain has weakness; combining them, many scholars (e.g. al-Albani) graded it sahih/hasan, while others still consider it weak."}, {"bn": "আয়েশা (রা.)-এর বর্ণনা: রাসুল ﷺ এক রাতে বাকি কবরস্থানে গিয়েছিলেন এবং বলেছিলেন, আল্লাহ মধ্য শাবানের রাতে কালব গোত্রের ছাগলের পশমের চেয়েও বেশি মানুষকে ক্ষমা করেন (সুনান তিরমিজি ৭৩৯)। ইমাম তিরমিজি উল্লেখ করেছেন যে ইমাম বুখারি এটিকে দুর্বল বলেছেন।", "en": "Aishah''s (RA) report that the Prophet ﷺ went to al-Baqi'' one night and said Allah forgives on the night of mid-Sha''ban more than the hairs of the sheep of Kalb (Jami'' at-Tirmidhi 739). At-Tirmidhi notes that al-Bukhari declared it weak."}, {"bn": "“মধ্য শাবানের রাতে নামাজ পড়ো এবং দিনে রোজা রাখো” (সুনান ইবনে মাজাহ ১৩৮৮) — এর সনদে একজন বর্ণনাকারীকে হাদিস জাল করার অভিযোগে অভিযুক্ত করা হয়েছে, তাই মুহাদ্দিসদের মতে এটি অত্যন্ত দুর্বল বা জাল।", "en": "“Pray in its night and fast its day” (Sunan Ibn Majah 1388) — its chain contains a narrator accused of fabricating hadith, so scholars rate it very weak or fabricated."}]}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ ১৩৯০; সুনান তিরমিজি ৭৩৯; সুনান ইবনে মাজাহ ১৩৮৮", "en": "Sunan Ibn Majah 1390; Jami'' at-Tirmidhi 739; Sunan Ibn Majah 1388"}, "check": true}, {"type": "differ", "title": {"bn": "রাতটির বিশেষ ফজিলত আছে কি না", "en": "Does the night have a special virtue?"}, "views": [{"label": {"bn": "ফজিলত আছে", "en": "It has a virtue"}, "text": {"bn": "রাতটি ক্ষমার রাত; একাকী নফল নামাজ, তিলাওয়াত, দোয়া ও ইস্তিগফার করা ভালো, তবে নির্দিষ্ট কোনো পদ্ধতি বা সম্মিলিত অনুষ্ঠান নেই। উপমহাদেশের অনেক হানাফি আলেমসহ পূর্বসূরি ও পরবর্তী বহু আলেম এই মত দিয়েছেন।", "en": "It is a night of forgiveness; individual voluntary prayer, recitation, dua and istighfar are good, but with no fixed method or collective ritual. Many Hanafi scholars of the subcontinent and many earlier and later scholars hold this view."}, "evidence": {"bn": "ক্ষমার হাদিসটির বিভিন্ন সূত্র মিলিয়ে তা হাসান/সহিহ পর্যায়ে পৌঁছে; কিছু তাবেয়ি এ রাতে ইবাদতে বিশেষ যত্ন নিতেন বলে বর্ণিত আছে।", "en": "The forgiveness hadith reaches hasan/sahih by its combined routes; some of the Tabi''un are reported to have given this night special care in worship."}}, {"label": {"bn": "বিশেষ ফজিলত প্রমাণিত নয়", "en": "No special virtue is established"}, "text": {"bn": "রাতটিকে অন্য সাধারণ রাতের মতোই দেখা উচিত; নিয়মিত তাহাজ্জুদ যে করে সে করবে, কিন্তু এ রাতকে আলাদা ইবাদতের জন্য নির্দিষ্ট করা ঠিক নয়।", "en": "The night should be treated like any other; whoever regularly prays tahajjud may do so, but singling it out for special worship is not correct."}, "evidence": {"bn": "প্রতিটি সনদ আলাদাভাবে দুর্বল, আর দুর্বল সূত্রের সমষ্টি দিয়ে নির্দিষ্ট ইবাদত প্রমাণ করা যায় না; রাসুল ﷺ বা সাহাবিদের থেকে এ রাতে বিশেষ আমলের সহিহ প্রমাণ নেই।", "en": "Each chain is weak on its own and weak routes cannot establish a specific act of worship; there is no sahih evidence of special practice on this night from the Prophet ﷺ or the Companions."}}]}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে আলেমরা একমত", "en": "What scholars agree on"}}, {"type": "list", "items": [{"bn": "এ রাতের জন্য নির্দিষ্ট রাকাত ও সূরার কোনো বিশেষ নামাজ (যেমন একশ রাকাতের “সালাতুল আলফিয়া”) প্রমাণিত নয়; এ সংক্রান্ত বর্ণনাগুলো জাল।", "en": "No special prayer with fixed rak''ahs and surahs (such as the hundred-rak''ah “salat al-alfiyyah”) is established; the reports about it are fabricated."}, {"bn": "হালুয়া-রুটি, আতশবাজি, আলোকসজ্জা ও কবরস্থানে দলবদ্ধ উৎসবের কোনো ভিত্তি নেই।", "en": "Halwa-ruti, fireworks, illuminations and group festivities at graveyards have no basis."}, {"bn": "“এ রাতে ভাগ্য লেখা হয়” — সূরা দুখানের (৪৪:৩–৪) “বরকতময় রাত” অধিকাংশ মুফাসসিরের মতে লাইলাতুল কদর, কারণ কুরআন রমজানে নাজিল হয়েছে (২:১৮৫, ৯৭:১)।", "en": "“Destinies are written this night” — the “blessed night” of Ad-Dukhan (44:3–4) is Laylat al-Qadr according to most commentators, since the Quran was revealed in Ramadan (2:185, 97:1)."}, {"bn": "শুধু ১৫ তারিখের রোজার হাদিসটি অত্যন্ত দুর্বল; তবে প্রতি মাসের ১৩, ১৪, ১৫ তারিখ (আইয়ামে বিয) এবং শাবানে বেশি রোজা রাখা সুন্নত, তাই এই নিয়তে ১৫ তারিখ রোজা রাখা যায়।", "en": "The hadith on fasting the 15th alone is very weak; but fasting the 13th–15th of every month and much of Sha''ban is sunnah, so one may fast the 15th with that intention."}, {"bn": "ক্ষমা পেতে শিরক ও মানুষের প্রতি বিদ্বেষ থেকে মুক্ত হওয়া জরুরি; এটি সব মতেই গুরুত্বপূর্ণ শিক্ষা।", "en": "To be forgiven one must be free of shirk and of hatred towards others; this lesson matters on every view."}]}, {"type": "note", "tone": "tip", "text": {"bn": "যে মতই অনুসরণ করুন, অন্য মতের মানুষকে কটাক্ষ করবেন না; এটি ইজতিহাদি বিষয়।", "en": "Whichever view you follow, do not belittle those who follow the other; it is a matter of scholarly judgement."}}]', 'in_review', 230 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3cd5469c-95e1-5819-b99e-1a35c119d5cc', id, 'fazilat-sadaqah', '{"bn": "সদকার ফজিলত", "en": "Virtues of sadaqah (charity)"}', '{"bn": "সদকা সম্পদ কমায় না, আল্লাহ হালাল উপার্জনের সদকা বাড়িয়ে দেন, আর সদকায়ে জারিয়া মৃত্যুর পরও চলতে থাকে।", "en": "Charity does not decrease wealth, Allah grows charity from pure earnings, and ongoing charity continues after death."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “যারা আল্লাহর পথে নিজেদের সম্পদ ব্যয় করে, তাদের উদাহরণ একটি শস্যদানার মতো, যা থেকে সাতটি শীষ জন্মায়, প্রতিটি শীষে একশ দানা; আর আল্লাহ যাকে ইচ্ছা আরও বহুগুণ বাড়িয়ে দেন।”", "en": "Allah says: “The example of those who spend their wealth in the way of Allah is like a seed that grows seven ears, in each ear a hundred grains; and Allah multiplies for whom He wills.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২৬১", "en": "Al-Baqarah 2:261"}}, {"type": "text", "text": {"bn": "সদকা সম্পদ কমায় না; ক্ষমা করার কারণে আল্লাহ বান্দার সম্মানই বাড়িয়ে দেন; আর যে আল্লাহর জন্য বিনয়ী হয়, আল্লাহ তাকে উঁচু করেন।", "en": "Charity does not decrease wealth; Allah only increases a servant in honour for forgiving; and whoever humbles himself for Allah, Allah raises him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৮৮", "en": "Sahih Muslim 2588"}}, {"type": "text", "text": {"bn": "যে হালাল উপার্জন থেকে একটি খেজুর পরিমাণও সদকা করে — আর আল্লাহ শুধু পবিত্র জিনিসই গ্রহণ করেন — আল্লাহ তা ডান হাতে গ্রহণ করে লালন করেন, যেমন তোমরা ঘোড়ার বাচ্চা লালন কর, শেষে তা পাহাড়ের সমান হয়ে যায়।", "en": "Whoever gives charity equal to a date from pure earnings — and Allah accepts only the pure — Allah takes it in His right hand and grows it as you raise a foal, until it becomes like a mountain."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪১০; সহিহ মুসলিম ১০১৪", "en": "Sahih al-Bukhari 1410; Sahih Muslim 1014"}}, {"type": "text", "text": {"bn": "অর্ধেক খেজুর দিয়ে হলেও জাহান্নাম থেকে বাঁচো।", "en": "Protect yourselves from the Fire even with half a date."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪১৭; সহিহ মুসলিম ১০১৬", "en": "Sahih al-Bukhari 1417; Sahih Muslim 1016"}}, {"type": "text", "text": {"bn": "প্রতিদিন সকালে দুজন ফেরেশতা নামেন; একজন বলেন: হে আল্লাহ, দানকারীকে বিনিময় দিন; আরেকজন বলেন: হে আল্লাহ, কৃপণের সম্পদ ধ্বংস করুন।", "en": "Every morning two angels descend; one says: O Allah, give the spender a replacement; the other says: O Allah, give the withholder ruin."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৪২; সহিহ মুসলিম ১০১০", "en": "Sahih al-Bukhari 1442; Sahih Muslim 1010"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন আল্লাহর ছায়ায় যে সাত শ্রেণির মানুষ থাকবে, তাদের একজন সেই ব্যক্তি, যে এত গোপনে সদকা করে যে তার বাম হাত জানে না ডান হাত কী দিল।", "en": "Among the seven shaded by Allah on the Last Day is one who gives charity so secretly that his left hand does not know what his right hand gave."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪২৩; সহিহ মুসলিম ১০৩১", "en": "Sahih al-Bukhari 1423; Sahih Muslim 1031"}}, {"type": "heading", "text": {"bn": "সদকায়ে জারিয়া", "en": "Ongoing charity"}}, {"type": "text", "text": {"bn": "মানুষ মারা গেলে তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান, এবং নেক সন্তান যে তার জন্য দোয়া করে।", "en": "When a person dies, his deeds end except three: ongoing charity, beneficial knowledge, or a righteous child who prays for him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৬৩১", "en": "Sahih Muslim 1631"}}, {"type": "note", "tone": "tip", "text": {"bn": "প্রতিটি ভালো কাজই সদকা (সহিহ বুখারি ৬০২১)। টাকা না থাকলেও হাসিমুখ, ভালো কথা, কারও কাজে সাহায্য — সবই সদকা।", "en": "Every good deed is charity (Sahih al-Bukhari 6021). Even without money, a smile, a kind word or helping someone is sadaqah."}}, {"type": "text", "text": {"bn": "সদকা গুনাহকে এমনভাবে নিভিয়ে দেয়, যেমন পানি আগুন নিভিয়ে দেয়।", "en": "Charity extinguishes sin as water extinguishes fire."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}]', 'in_review', 240 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b02ae94b-e5c7-5ccb-b1e0-546675182642', id, 'fazilat-zakat', '{"bn": "যাকাতের ফজিলত", "en": "Virtues of zakat"}', '{"bn": "যাকাত ইসলামের স্তম্ভ, সম্পদ ও মনকে পবিত্র করে, জান্নাতের পথ সহজ করে; আর না দেওয়ার কঠিন পরিণাম।", "en": "Zakat is a pillar of Islam that purifies wealth and soul and leads to Paradise; withholding it has a severe consequence."}', 'basic', '[{"type": "text", "text": {"bn": "ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত: আল্লাহ ছাড়া কোনো ইলাহ নেই ও মুহাম্মাদ ﷺ আল্লাহর রাসুল — এই সাক্ষ্য দেওয়া, নামাজ কায়েম করা, যাকাত দেওয়া, হজ করা এবং রমজানের রোজা রাখা।", "en": "Islam is built on five: testifying there is no god but Allah and Muhammad is His Messenger, establishing prayer, giving zakat, hajj and fasting Ramadan."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮; সহিহ মুসলিম ১৬", "en": "Sahih al-Bukhari 8; Sahih Muslim 16"}}, {"type": "text", "text": {"bn": "আল্লাহ বলেন: “তাদের সম্পদ থেকে সদকা (যাকাত) গ্রহণ করো, যা দিয়ে তুমি তাদের পবিত্র ও পরিশুদ্ধ করবে।”", "en": "Allah says: “Take from their wealth a charity by which you purify them and cause them increase.”"}}, {"type": "ref", "text": {"bn": "সূরা তাওবা ৯:১০৩", "en": "At-Tawbah 9:103"}}, {"type": "text", "text": {"bn": "আল্লাহ বলেন: “নিশ্চয়ই যারা ঈমান আনে, নেক আমল করে, নামাজ কায়েম করে ও যাকাত দেয়, তাদের প্রতিদান তাদের রবের কাছে; তাদের কোনো ভয় নেই, তারা চিন্তিতও হবে না।”", "en": "Allah says: “Those who believe, do righteous deeds, establish prayer and give zakat will have their reward with their Lord; no fear will be on them, nor will they grieve.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২৭৭", "en": "Al-Baqarah 2:277"}}, {"type": "text", "text": {"bn": "এক ব্যক্তি জিজ্ঞেস করল, এমন আমল বলুন যা আমাকে জান্নাতে নিয়ে যাবে। রাসুল ﷺ বললেন: আল্লাহর ইবাদত করো, তাঁর সঙ্গে কিছু শরিক করো না, নামাজ কায়েম করো, যাকাত দাও এবং আত্মীয়তার সম্পর্ক বজায় রাখো।", "en": "A man asked for a deed that would take him to Paradise. The Prophet ﷺ said: worship Allah without associating anything with Him, establish prayer, give zakat and keep ties of kinship."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৯৬; সহিহ মুসলিম ১৩", "en": "Sahih al-Bukhari 1396; Sahih Muslim 13"}}, {"type": "note", "tone": "warn", "text": {"bn": "যাকে আল্লাহ সম্পদ দিয়েছেন কিন্তু সে যাকাত দেয়নি, কিয়ামতের দিন তার সম্পদকে একটি বিষধর টেকো সাপ বানানো হবে, যা তার গলা পেঁচিয়ে ধরে বলবে: আমি তোমার সম্পদ, আমি তোমার সঞ্চয় (সহিহ বুখারি ১৪০৩)।", "en": "Whoever Allah gave wealth and did not pay its zakat, his wealth will be made a bald venomous snake on the Day of Resurrection, coiling around his neck and saying: I am your wealth, I am your treasure (Sahih al-Bukhari 1403)."}}, {"type": "text", "text": {"bn": "যাকাত গরিবের হক, দাতার দয়া নয়; এটি দিলে সম্পদে বরকত আসে এবং মন কৃপণতা থেকে মুক্ত হয়। সদকা সম্পদ কমায় না (সহিহ মুসলিম ২৫৮৮)।", "en": "Zakat is the right of the poor, not a favour from the giver; it brings blessing to wealth and frees the heart from stinginess. Charity does not decrease wealth (Sahih Muslim 2588)."}}, {"type": "note", "tone": "info", "text": {"bn": "যাকাতের নিসাব, হার ও খাত জানতে “যাকাত ও সদকা” বিভাগ দেখুন।", "en": "For nisab, rates and recipients, see the Zakat and Sadaqah section."}}]', 'in_review', 250 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'aa04c452-c96e-5bc6-9552-9b336032151d', id, 'fazilat-hajj-umrah', '{"bn": "হজ ও উমরাহর ফজিলত", "en": "Virtues of hajj and umrah"}', '{"bn": "মাবরুর হজের প্রতিদান জান্নাত; গুনাহমুক্ত হজ মানুষকে নবজাতকের মতো নিষ্পাপ করে দেয়, আর এক উমরাহ থেকে আরেক উমরাহ কাফফারা।", "en": "The reward of an accepted hajj is Paradise; a sin-free hajj leaves one like a newborn, and umrah to umrah is expiation."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “মানুষের ওপর আল্লাহর জন্য এই ঘরের হজ করা ফরজ, যে সেখানে যাওয়ার সামর্থ্য রাখে।”", "en": "Allah says: “Pilgrimage to the House is a duty owed to Allah by people who are able to find a way there.”"}}, {"type": "ref", "text": {"bn": "সূরা আলে ইমরান ৩:৯৭", "en": "Al ''Imran 3:97"}}, {"type": "text", "text": {"bn": "যে আল্লাহর জন্য হজ করে এবং তাতে অশ্লীল কথা ও গুনাহ থেকে বেঁচে থাকে, সে এমনভাবে ফিরে আসে যেন সেদিন মা তাকে জন্ম দিয়েছে।", "en": "Whoever performs hajj for Allah without obscenity or sin returns as on the day his mother bore him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২১; সহিহ মুসলিম ১৩৫০", "en": "Sahih al-Bukhari 1521; Sahih Muslim 1350"}}, {"type": "text", "text": {"bn": "এক উমরাহ থেকে আরেক উমরাহ মাঝখানের গুনাহের কাফফারা, আর মাবরুর (কবুল) হজের প্রতিদান জান্নাত ছাড়া আর কিছু নয়।", "en": "One umrah to the next expiates what is between them, and the reward of an accepted hajj is nothing but Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৭৩; সহিহ মুসলিম ১৩৪৯", "en": "Sahih al-Bukhari 1773; Sahih Muslim 1349"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ-কে জিজ্ঞেস করা হলো, কোন আমল শ্রেষ্ঠ? বললেন: আল্লাহ ও রাসুলের প্রতি ঈমান; তারপর আল্লাহর পথে জিহাদ; তারপর মাবরুর হজ।", "en": "He ﷺ was asked which deed is best. He said: faith in Allah and His Messenger, then jihad in Allah''s path, then an accepted hajj."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৬", "en": "Sahih al-Bukhari 26"}}, {"type": "text", "text": {"bn": "আয়েশা (রা.) জিহাদের কথা বললে রাসুল ﷺ বলেন: তোমাদের (নারীদের) জন্য শ্রেষ্ঠ জিহাদ হলো মাবরুর হজ।", "en": "When Aishah (RA) asked about jihad, he ﷺ said: the best jihad for you (women) is an accepted hajj."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২০", "en": "Sahih al-Bukhari 1520"}}, {"type": "text", "text": {"bn": "হজ ও উমরাহ পরপর করো, কারণ এ দুটি দারিদ্র্য ও গুনাহ এমনভাবে দূর করে, যেমন হাপর লোহা, সোনা ও রুপার ময়লা দূর করে।", "en": "Follow hajj with umrah, for they remove poverty and sins as the bellows removes impurity from iron, gold and silver."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি; সুনান নাসায়ি", "en": "Jami'' at-Tirmidhi; Sunan an-Nasa''i"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "রমজানে উমরাহ করা হজের সমান সওয়াব (সহিহ মুসলিম ১২৫৬), তবে তা ফরজ হজের বিকল্প নয়।", "en": "Umrah in Ramadan equals hajj in reward (Sahih Muslim 1256), but it does not replace the obligatory hajj."}}, {"type": "note", "tone": "info", "text": {"bn": "হজ ও উমরাহর নিয়ম জানতে “হজ” ও “উমরাহ” বিভাগ দেখুন।", "en": "For how to perform them, see the Hajj and Umrah sections."}}]', 'in_review', 260 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '02578f51-25bd-5c7f-804f-f75ce482fd02', id, 'fazilat-ilm', '{"bn": "দ্বীনি জ্ঞান অর্জনের ফজিলত", "en": "Virtues of seeking knowledge"}', '{"bn": "জ্ঞানের পথে চললে আল্লাহ জান্নাতের পথ সহজ করেন; আল্লাহ যার কল্যাণ চান তাকে দ্বীনের বুঝ দেন।", "en": "Whoever walks a path of knowledge, Allah eases his path to Paradise; when Allah wills good for someone, He gives him understanding of the religion."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “তোমাদের মধ্যে যারা ঈমান এনেছে এবং যাদের জ্ঞান দেওয়া হয়েছে, আল্লাহ তাদের মর্যাদা বহু স্তরে উঁচু করবেন।” এবং: “বলো, যারা জানে আর যারা জানে না, তারা কি সমান?”", "en": "Allah says: “Allah will raise those who have believed among you and those given knowledge by degrees.” And: “Say: are those who know equal to those who do not know?”"}}, {"type": "ref", "text": {"bn": "সূরা মুজাদালা ৫৮:১১; সূরা যুমার ৩৯:৯", "en": "Al-Mujadilah 58:11; Az-Zumar 39:9"}}, {"type": "arabic", "label": {"bn": "কুরআনে শেখানো দোয়া", "en": "A dua taught in the Quran"}, "ar": "رَبِّ زِدْنِي عِلْمًا", "pron": {"bn": "রব্বি যিদনী ইলমা", "en": "Rabbi zidni ''ilma"}, "meaning": {"bn": "হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন।", "en": "My Lord, increase me in knowledge."}, "ref": {"bn": "সূরা ত্বা-হা ২০:১১৪", "en": "Ta-Ha 20:114"}}, {"type": "text", "text": {"bn": "আল্লাহ যার কল্যাণ চান, তাকে দ্বীনের গভীর বুঝ দান করেন।", "en": "When Allah wills good for someone, He gives him understanding of the religion."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৭১; সহিহ মুসলিম ১০৩৭", "en": "Sahih al-Bukhari 71; Sahih Muslim 1037"}}, {"type": "text", "text": {"bn": "যে জ্ঞান অর্জনের জন্য কোনো পথে চলে, আল্লাহ তার জন্য জান্নাতের পথ সহজ করে দেন।", "en": "Whoever travels a path seeking knowledge, Allah makes easy for him a path to Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬৯৯", "en": "Sahih Muslim 2699"}}, {"type": "text", "text": {"bn": "ফেরেশতারা জ্ঞান অন্বেষণকারীর সন্তুষ্টিতে তাদের ডানা বিছিয়ে দেন; আলেমদের জন্য আসমান-জমিনের সবাই, এমনকি পানির মাছও ক্ষমা প্রার্থনা করে; আর আলেমরা নবীদের উত্তরাধিকারী।", "en": "The angels lower their wings for the seeker of knowledge out of pleasure; everyone in the heavens and earth, even the fish in the water, seeks forgiveness for the scholar; and the scholars are the heirs of the prophets."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৩৬৪১; সুনান তিরমিজি ২৬৮২", "en": "Sunan Abi Dawud 3641; Jami'' at-Tirmidhi 2682"}}, {"type": "text", "text": {"bn": "প্রত্যেক মুসলিমের ওপর জ্ঞান অর্জন করা ফরজ।", "en": "Seeking knowledge is an obligation on every Muslim."}}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ ২২৪", "en": "Sunan Ibn Majah 224"}}, {"type": "note", "tone": "info", "text": {"bn": "শেষ হাদিসটির প্রতিটি সনদ দুর্বল, তবে অনেক সূত্রে আসায় বেশ কয়েকজন মুহাদ্দিস একে হাসান/সহিহ বলেছেন। এখানে “জ্ঞান” বলতে মূলত সেই দ্বীনি জ্ঞান বোঝায় যা ছাড়া ফরজ ইবাদত ও হালাল-হারাম জানা যায় না।", "en": "Each chain of the last hadith is weak, but due to its many routes several scholars graded it hasan/sahih. “Knowledge” here mainly means the religious knowledge needed for obligatory worship and halal and haram."}}, {"type": "note", "tone": "warn", "text": {"bn": "প্রচলিত কথা “জ্ঞান অর্জনের জন্য প্রয়োজনে চীন দেশে যাও” রাসুল ﷺ-এর হাদিস হিসেবে প্রমাণিত নয়; মুহাদ্দিসদের মতে এটি অত্যন্ত দুর্বল বা জাল।", "en": "The popular saying “seek knowledge even in China” is not established as a hadith; scholars rate it very weak or fabricated."}}]', 'in_review', 270 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4a90206c-e79e-5390-a225-0569bee9c99c', id, 'fazilat-akhlaq', '{"bn": "উত্তম চরিত্রের ফজিলত", "en": "Virtues of good character"}', '{"bn": "কিয়ামতের দিন মিজানে উত্তম চরিত্রের চেয়ে ভারী কিছু নেই; ভালো চরিত্রের মানুষই শ্রেষ্ঠ মানুষ।", "en": "Nothing is heavier on the scale on the Last Day than good character; the best people are those best in character."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ রাসুল ﷺ সম্পর্কে বলেন: “নিশ্চয়ই তুমি মহান চরিত্রের অধিকারী।”", "en": "Allah says of the Prophet ﷺ: “And indeed, you are of a great moral character.”"}}, {"type": "ref", "text": {"bn": "সূরা কলম ৬৮:৪", "en": "Al-Qalam 68:4"}}, {"type": "text", "text": {"bn": "তোমাদের মধ্যে সর্বোত্তম সে, যার চরিত্র সবচেয়ে সুন্দর।", "en": "The best of you are those with the best character."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৫৫৯; সহিহ মুসলিম ২৩২১", "en": "Sahih al-Bukhari 3559; Sahih Muslim 2321"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন মুমিনের মিজানে উত্তম চরিত্রের চেয়ে ভারী আর কিছু থাকবে না।", "en": "Nothing will be heavier on the believer''s scale on the Day of Resurrection than good character."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২০০২; সুনান আবু দাউদ ৪৭৯৯", "en": "Jami'' at-Tirmidhi 2002; Sunan Abi Dawud 4799"}}, {"type": "text", "text": {"bn": "মুমিন তার উত্তম চরিত্রের মাধ্যমে সারা দিন রোজাদার ও সারা রাত নামাজ আদায়কারীর মর্যাদা লাভ করে।", "en": "By good character a believer reaches the rank of one who fasts by day and prays by night."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৪৭৯৮", "en": "Sunan Abi Dawud 4798"}}, {"type": "text", "text": {"bn": "সবচেয়ে বেশি যে জিনিস মানুষকে জান্নাতে নিয়ে যাবে তা হলো আল্লাহভীতি ও উত্তম চরিত্র।", "en": "What most admits people into Paradise is fear of Allah and good character."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২০০৪", "en": "Jami'' at-Tirmidhi 2004"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে হকের ওপর থেকেও ঝগড়া ছেড়ে দেয়, তার জন্য আমি জান্নাতের পাশে একটি ঘরের জামিন; যে ঠাট্টা করেও মিথ্যা বলে না, তার জন্য জান্নাতের মাঝখানে একটি ঘর; আর যার চরিত্র উত্তম, তার জন্য জান্নাতের সর্বোচ্চ স্থানে একটি ঘর।", "en": "I guarantee a house on the outskirts of Paradise for whoever leaves arguing even when right, a house in its middle for whoever leaves lying even in jest, and a house in its highest part for whoever has good character."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৪৮০০", "en": "Sunan Abi Dawud 4800"}}, {"type": "note", "tone": "tip", "text": {"bn": "চরিত্র চর্চা শুরু হয় ঘর থেকে: পরিবারের সঙ্গে নরম কথা, রাগ নিয়ন্ত্রণ, ক্ষমা করা ও প্রতিশ্রুতি রক্ষা।", "en": "Character begins at home: gentle words with family, controlling anger, forgiving and keeping promises."}}]', 'in_review', 280 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fc15c20b-ddd8-5144-839f-d893049401da', id, 'fazilat-parents', '{"bn": "মা-বাবার সঙ্গে সদ্ব্যবহারের ফজিলত", "en": "Virtues of kindness to parents"}', '{"bn": "আল্লাহর ইবাদতের পরেই মা-বাবার প্রতি সদ্ব্যবহারের নির্দেশ; মায়ের হক তিন গুণ, আর বৃদ্ধ মা-বাবার সেবা জান্নাতের পথ।", "en": "After worshipping Allah comes kindness to parents; the mother''s right is threefold, and serving elderly parents is a path to Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “তোমার রব নির্দেশ দিয়েছেন, তাঁকে ছাড়া কারও ইবাদত করো না এবং মা-বাবার সঙ্গে সদ্ব্যবহার করো। তাদের একজন বা দুজনই বার্ধক্যে পৌঁছালে তাদের “উফ” পর্যন্ত বলো না, ধমক দিয়ো না, বরং সম্মানের সঙ্গে নরম কথা বলো।”", "en": "Allah says: “Your Lord has decreed that you worship none but Him, and be good to parents. If one or both reach old age with you, do not say to them ‘uff’ or repel them, but speak to them a noble word.”"}}, {"type": "ref", "text": {"bn": "সূরা বনি ইসরাঈল ১৭:২৩–২৪", "en": "Al-Isra 17:23–24"}}, {"type": "arabic", "label": {"bn": "মা-বাবার জন্য দোয়া", "en": "Dua for parents"}, "ar": "رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا", "pron": {"bn": "রব্বির হামহুমা কামা রব্বাইয়ানী সাগীরা", "en": "Rabbir-hamhuma kama rabbayani saghira"}, "meaning": {"bn": "হে আমার রব, তাদের প্রতি দয়া করুন, যেমন তারা শৈশবে আমাকে লালন-পালন করেছেন।", "en": "My Lord, have mercy on them as they raised me when I was small."}, "ref": {"bn": "সূরা বনি ইসরাঈল ১৭:২৪", "en": "Al-Isra 17:24"}}, {"type": "text", "text": {"bn": "আল্লাহর কাছে প্রিয় আমলের তালিকায় সময়মতো নামাজের পরেই মা-বাবার সঙ্গে সদ্ব্যবহার।", "en": "In the list of deeds beloved to Allah, kindness to parents comes right after prayer on time."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫২৭", "en": "Sahih al-Bukhari 527"}}, {"type": "text", "text": {"bn": "এক ব্যক্তি জিজ্ঞেস করল, আমার সদ্ব্যবহারের সবচেয়ে বেশি হকদার কে? রাসুল ﷺ বললেন: তোমার মা। তারপর? তোমার মা। তারপর? তোমার মা। তারপর? তোমার বাবা।", "en": "A man asked who most deserves his good companionship. He ﷺ said: your mother. Then? Your mother. Then? Your mother. Then? Your father."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৯৭১; সহিহ মুসলিম ২৫৪৮", "en": "Sahih al-Bukhari 5971; Sahih Muslim 2548"}}, {"type": "text", "text": {"bn": "তার নাক ধুলোয় মলিন হোক, যে মা-বাবার একজন বা দুজনকেই বার্ধক্যে পেল, অথচ (তাদের সেবা করে) জান্নাতে যেতে পারল না।", "en": "May his nose be in the dust, the one who finds one or both parents in old age and does not enter Paradise (by serving them)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৫১", "en": "Sahih Muslim 2551"}}, {"type": "text", "text": {"bn": "রবের সন্তুষ্টি বাবার সন্তুষ্টিতে, আর রবের অসন্তুষ্টি বাবার অসন্তুষ্টিতে।", "en": "The Lord''s pleasure lies in the father''s pleasure, and His displeasure in the father''s displeasure."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ১৮৯৯", "en": "Jami'' at-Tirmidhi 1899"}}, {"type": "text", "text": {"bn": "এক সাহাবি জিহাদে যাওয়ার অনুমতি চাইলে রাসুল ﷺ জিজ্ঞেস করলেন, তোমার মা আছেন? তিনি হ্যাঁ বললে রাসুল ﷺ বললেন: তাঁর সেবায় লেগে থাকো, কারণ জান্নাত তাঁর পায়ের কাছে।", "en": "A Companion sought permission for jihad; the Prophet ﷺ asked if his mother was alive, then said: stay with her, for Paradise is at her feet."}}, {"type": "ref", "text": {"bn": "সুনান নাসায়ি", "en": "Sunan an-Nasa''i"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "“মায়ের পায়ের নিচে সন্তানের জান্নাত” — প্রচলিত এই শব্দে বর্ণনাটি দুর্বল; তবে উপরের নাসায়ির বর্ণনাটি একই অর্থে এবং মুহাদ্দিসদের মতে হাসান।", "en": "The popular wording “Paradise lies under the feet of mothers” is weak, but the an-Nasa''i narration above carries the same meaning and is graded hasan."}}, {"type": "note", "tone": "warn", "text": {"bn": "মা-বাবার অবাধ্যতা শিরকের পরেই সবচেয়ে বড় গুনাহগুলোর একটি (সহিহ বুখারি ২৬৫৪)।", "en": "Disobedience to parents is among the greatest sins, mentioned right after shirk (Sahih al-Bukhari 2654)."}}, {"type": "note", "tone": "tip", "text": {"bn": "মা-বাবা মারা গেলেও তাদের জন্য দোয়া, তাদের পক্ষ থেকে সদকা এবং তাদের বন্ধু ও আত্মীয়দের সম্মান করার মাধ্যমে সদ্ব্যবহার চালিয়ে যাওয়া যায় (সহিহ মুসলিম ১৬৩১)।", "en": "Even after they pass away, kindness continues through dua, charity on their behalf and honouring their friends and relatives (Sahih Muslim 1631)."}}]', 'in_review', 290 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '914fa59e-fe6f-50ca-bc7e-e7258654640d', id, 'fazilat-silat-rahim', '{"bn": "আত্মীয়তার সম্পর্ক রক্ষার ফজিলত", "en": "Virtues of keeping ties of kinship"}', '{"bn": "আত্মীয়তার সম্পর্ক রক্ষা করলে রিজিক ও আয়ু বরকতময় হয়; সম্পর্ক ছিন্নকারী জান্নাতে যাবে না।", "en": "Keeping ties of kinship brings blessing in provision and life; one who cuts them will not enter Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “আল্লাহকে ভয় করো, যাঁর নামে তোমরা একে অপরের কাছে চাও, এবং আত্মীয়তার সম্পর্কের ব্যাপারে সতর্ক থাকো।”", "en": "Allah says: “Fear Allah, through whom you ask one another, and the wombs (ties of kinship).”"}}, {"type": "ref", "text": {"bn": "সূরা নিসা ৪:১", "en": "An-Nisa 4:1"}}, {"type": "text", "text": {"bn": "যে চায় তার রিজিক প্রশস্ত হোক এবং আয়ু বাড়ুক, সে যেন আত্মীয়তার সম্পর্ক বজায় রাখে।", "en": "Whoever would like his provision expanded and his life extended, let him keep ties of kinship."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৯৮৬; সহিহ মুসলিম ২৫৫৭", "en": "Sahih al-Bukhari 5986; Sahih Muslim 2557"}}, {"type": "text", "text": {"bn": "প্রকৃত সম্পর্ক রক্ষাকারী সে নয়, যে শুধু প্রতিদানে সম্পর্ক রাখে; বরং সে-ই প্রকৃত রক্ষাকারী, যার সঙ্গে সম্পর্ক ছিন্ন করা হলেও সে তা জোড়া লাগায়।", "en": "The one who maintains ties is not the one who merely reciprocates; it is the one who rejoins them when they are cut."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৯৯১", "en": "Sahih al-Bukhari 5991"}}, {"type": "text", "text": {"bn": "এক ব্যক্তি বলল, আমার আত্মীয়দের সঙ্গে সম্পর্ক রাখি, তারা ছিন্ন করে; ভালো করি, তারা মন্দ করে। রাসুল ﷺ বললেন: তুমি যেমন বললে তেমন হলে তুমি যেন তাদের মুখে গরম ছাই পুরে দিচ্ছ, আর যতক্ষণ তুমি এমন থাকবে, আল্লাহর পক্ষ থেকে একজন সাহায্যকারী তোমার সঙ্গে থাকবে।", "en": "A man said: I keep ties with my relatives and they cut me; I do good to them and they harm me. He ﷺ said: if you are as you say, it is as if you feed them hot ashes, and a helper from Allah will remain with you as long as you continue."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৫৮", "en": "Sahih Muslim 2558"}}, {"type": "note", "tone": "warn", "text": {"bn": "আত্মীয়তার সম্পর্ক ছিন্নকারী জান্নাতে প্রবেশ করবে না (সহিহ বুখারি ৫৯৮৪)।", "en": "The one who severs ties of kinship will not enter Paradise (Sahih al-Bukhari 5984)."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়মিত খোঁজখবর নেওয়া, ফোন করা, উপহার দেওয়া, বিপদে পাশে থাকা — সবই সম্পর্ক রক্ষা; অভাবী আত্মীয়কে সদকা দিলে সদকা ও আত্মীয়তা দুটোরই সওয়াব।", "en": "Checking in, calling, giving gifts and standing by them in hardship all keep ties; charity to a needy relative earns the reward of both charity and kinship."}}]', 'in_review', 300 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'd5f8612d-cd3e-56cf-b756-7c136698a586', id, 'fazilat-sabr', '{"bn": "সবর (ধৈর্য)-এর ফজিলত", "en": "Virtues of patience (sabr)"}', '{"bn": "আল্লাহ ধৈর্যশীলদের সঙ্গে আছেন; তাদের প্রতিদান হিসাব ছাড়া, আর ছোট কষ্টেও গুনাহ মাফ হয়।", "en": "Allah is with the patient; their reward is without measure, and even small hardships erase sins."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “হে মুমিনগণ, ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সঙ্গে আছেন।” আরও বলেন: “ধৈর্যশীলদের প্রতিদান দেওয়া হবে হিসাব ছাড়াই।”", "en": "Allah says: “O you who believe, seek help through patience and prayer; indeed Allah is with the patient.” And: “The patient will be given their reward without account.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৫৩; সূরা যুমার ৩৯:১০", "en": "Al-Baqarah 2:153; Az-Zumar 39:10"}}, {"type": "text", "text": {"bn": "“আমি অবশ্যই তোমাদের পরীক্ষা করব কিছু ভয়, ক্ষুধা এবং সম্পদ, জীবন ও ফসলের ক্ষতি দিয়ে; আর ধৈর্যশীলদের সুসংবাদ দাও — যারা বিপদে পড়লে বলে: আমরা আল্লাহর জন্য, আর তাঁর কাছেই ফিরে যাব। তাদের ওপর রবের পক্ষ থেকে রহমত ও অনুগ্রহ, আর তারাই সঠিক পথে আছে।”", "en": "“We will surely test you with some fear, hunger and loss of wealth, lives and fruits; but give good news to the patient, who say when struck by calamity: ‘To Allah we belong and to Him we return.’ Upon them are blessings and mercy from their Lord, and they are the rightly guided.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৫৫–১৫৭", "en": "Al-Baqarah 2:155–157"}}, {"type": "text", "text": {"bn": "ধৈর্যের চেয়ে উত্তম ও প্রশস্ত দান আর কাউকে দেওয়া হয়নি।", "en": "No one has been given a gift better and more vast than patience."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৬৯; সহিহ মুসলিম ১০৫৩", "en": "Sahih al-Bukhari 1469; Sahih Muslim 1053"}}, {"type": "text", "text": {"bn": "মুমিনের ব্যাপারটি আশ্চর্যজনক; তার সবকিছুই কল্যাণকর। সুখ পেলে শোকর করে, তা তার জন্য কল্যাণ; বিপদে পড়লে সবর করে, তাও তার জন্য কল্যাণ।", "en": "How wonderful is the affair of the believer; all of it is good. If good befalls him he is grateful, and that is good for him; if harm befalls him he is patient, and that is good for him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৯৯৯", "en": "Sahih Muslim 2999"}}, {"type": "text", "text": {"bn": "মুসলিমের যে কোনো ক্লান্তি, অসুখ, দুশ্চিন্তা, দুঃখ, কষ্ট ও মনোবেদনা, এমনকি একটি কাঁটা বিঁধলেও, আল্লাহ এর মাধ্যমে তার গুনাহ মাফ করে দেন।", "en": "No fatigue, illness, worry, grief, harm or distress befalls a Muslim, even a thorn''s prick, except that Allah expiates some of his sins by it."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৬৪১; সহিহ মুসলিম ২৫৭৩", "en": "Sahih al-Bukhari 5641; Sahih Muslim 2573"}}, {"type": "text", "text": {"bn": "প্রকৃত সবর হলো বিপদের প্রথম আঘাতের সময় ধৈর্য ধরা।", "en": "True patience is at the first stroke of calamity."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২৮৩; সহিহ মুসলিম ৯২৬", "en": "Sahih al-Bukhari 1283; Sahih Muslim 926"}}, {"type": "arabic", "label": {"bn": "বিপদের সময় দোয়া", "en": "Dua at a time of loss"}, "ar": "إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللّٰهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا", "pron": {"bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন, আল্লাহুম্মা''জুরনী ফী মুসীবাতী, ওয়া আখলিফ লী খাইরাম মিনহা", "en": "Inna lillahi wa inna ilayhi raji''un, Allahumma''jurni fi musibati, wa akhlif li khayram minha"}, "meaning": {"bn": "আমরা আল্লাহর জন্য এবং তাঁর কাছেই ফিরে যাব। হে আল্লাহ, আমার এই বিপদে আমাকে প্রতিদান দিন এবং এর বদলে এর চেয়ে উত্তম কিছু দিন।", "en": "To Allah we belong and to Him we return. O Allah, reward me in my affliction and replace it for me with something better."}, "ref": {"bn": "সহিহ মুসলিম ৯১৮", "en": "Sahih Muslim 918"}}, {"type": "text", "text": {"bn": "উম্মে সালামা (রা.) স্বামী আবু সালামার মৃত্যুর পর এই দোয়া পড়েছিলেন, আর আল্লাহ তাঁকে বদলে রাসুল ﷺ-কে স্বামী হিসেবে দিয়েছিলেন।", "en": "Umm Salamah (RA) said this after her husband Abu Salamah died, and Allah replaced him for her with the Prophet ﷺ."}}]', 'in_review', 310 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '139b88d1-d10f-51e2-8624-92ef25bc7710', id, 'fazilat-rogi-dekha', '{"bn": "রোগী দেখতে যাওয়ার ফজিলত", "en": "Virtues of visiting the sick"}', '{"bn": "রোগী দেখতে যাওয়া মুসলিমের হক; যতক্ষণ রোগীর কাছে থাকে, ততক্ষণ সে জান্নাতের বাগানে থাকে।", "en": "Visiting the sick is a Muslim''s right; while with the sick, the visitor is in the harvest of Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "এক মুসলিমের ওপর আরেক মুসলিমের পাঁচটি হক: সালামের জবাব দেওয়া, রোগী দেখতে যাওয়া, জানাযার সঙ্গে যাওয়া, দাওয়াত কবুল করা এবং হাঁচিদাতার জবাব দেওয়া।", "en": "A Muslim has five rights over another: returning the greeting, visiting the sick, following the funeral, accepting the invitation and replying to one who sneezes."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২৪০; সহিহ মুসলিম ২১৬২", "en": "Sahih al-Bukhari 1240; Sahih Muslim 2162"}}, {"type": "text", "text": {"bn": "যে মুসলিম তার অসুস্থ ভাইকে দেখতে যায়, সে ফিরে আসা পর্যন্ত জান্নাতের বাগানে (ফল আহরণে) থাকে।", "en": "Whoever visits a sick Muslim remains in the harvest of Paradise until he returns."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৬৮", "en": "Sahih Muslim 2568"}}, {"type": "text", "text": {"bn": "হাদিসে কুদসিতে আল্লাহ কিয়ামতের দিন বলবেন: হে আদম সন্তান, আমি অসুস্থ ছিলাম, তুমি আমাকে দেখতে আসোনি। সে বলবে: আপনি তো জগতের রব, কীভাবে দেখতে যাব? আল্লাহ বলবেন: তুমি কি জানতে না আমার অমুক বান্দা অসুস্থ ছিল? তাকে দেখতে গেলে আমাকে তার কাছেই পেতে।", "en": "In a hadith qudsi, Allah will say on the Last Day: O son of Adam, I was ill and you did not visit Me. He will say: how could I, when You are Lord of the worlds? He will say: did you not know My servant so-and-so was ill? Had you visited him, you would have found Me with him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৬৯", "en": "Sahih Muslim 2569"}}, {"type": "text", "text": {"bn": "কোনো মুসলিম সকালে রোগী দেখতে গেলে সন্ধ্যা পর্যন্ত সত্তর হাজার ফেরেশতা তার জন্য দোয়া করে, আর সন্ধ্যায় গেলে সকাল পর্যন্ত।", "en": "If a Muslim visits a sick person in the morning, seventy thousand angels pray for him until evening, and if in the evening, until morning."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "heading", "text": {"bn": "রোগীর জন্য দোয়া", "en": "Dua for the sick"}}, {"type": "arabic", "ar": "لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللّٰهُ", "pron": {"bn": "লা বা''সা, তাহূরুন ইনশাআল্লাহ", "en": "La ba''s, tahurun in sha Allah"}, "meaning": {"bn": "কোনো চিন্তা নেই, ইনশাআল্লাহ এটি (গুনাহ থেকে) পবিত্রকারী।", "en": "No harm; it is a purification, if Allah wills."}, "ref": {"bn": "সহিহ বুখারি", "en": "Sahih al-Bukhari"}, "check": true}, {"type": "arabic", "label": {"bn": "সাতবার", "en": "Seven times"}, "ar": "أَسْأَلُ اللّٰهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ", "pron": {"bn": "আসআলুল্লাহাল আযীম, রব্বাল আরশিল আযীম, আঁই ইয়াশফিয়াক", "en": "As''alullahal-''azim, rabbal-''arshil-''azim, an yashfiyak"}, "meaning": {"bn": "আমি মহান আল্লাহর কাছে, যিনি মহান আরশের রব, প্রার্থনা করছি তিনি যেন তোমাকে সুস্থ করেন।", "en": "I ask Allah the Magnificent, Lord of the magnificent Throne, to cure you."}, "ref": {"bn": "সুনান আবু দাউদ; সুনান তিরমিজি", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "রোগীর কাছে বেশি সময় বসবেন না, আশার কথা বলুন, আর তাঁর কাছে নিজের জন্যও দোয়া চাইতে পারেন।", "en": "Do not stay too long, speak words of hope, and you may ask the sick person to pray for you."}}]', 'in_review', 320 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6cf0c2f1-7ca9-5195-a929-66c88e5963a3', id, 'fazilat-salam-hasi', '{"bn": "সালাম, হাসিমুখ ও রাস্তা থেকে কষ্টদায়ক জিনিস সরানো", "en": "Salam, a smiling face and removing harm from the road"}', '{"bn": "ছোট ছোট আমলের বড় সওয়াব: সালামের প্রসার ভালোবাসা আনে, হাসিমুখ সদকা, আর রাস্তা থেকে কাঁটা সরিয়ে একজন জান্নাত পেয়েছে।", "en": "Small deeds, great rewards: spreading salam brings love, a smile is charity, and a man entered Paradise for removing a thorny branch from the road."}', 'basic', '[{"type": "heading", "text": {"bn": "সালামের প্রসার", "en": "Spreading salam"}}, {"type": "text", "text": {"bn": "তোমরা ঈমান না আনা পর্যন্ত জান্নাতে যাবে না, আর পরস্পরকে না ভালোবাসা পর্যন্ত ঈমানদার হবে না। আমি কি তোমাদের এমন জিনিস বলব না যা করলে তোমরা পরস্পরকে ভালোবাসবে? তোমাদের মাঝে সালামের প্রসার ঘটাও।", "en": "You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I tell you something that, if you do it, you will love one another? Spread salam among you."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৪", "en": "Sahih Muslim 54"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ-কে জিজ্ঞেস করা হলো, ইসলামের কোন কাজ উত্তম? বললেন: খাবার খাওয়ানো এবং পরিচিত-অপরিচিত সবাইকে সালাম দেওয়া।", "en": "He ﷺ was asked which act of Islam is best. He said: feeding people and greeting those you know and those you do not."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২; সহিহ মুসলিম ৩৯", "en": "Sahih al-Bukhari 12; Sahih Muslim 39"}}, {"type": "arabic", "label": {"bn": "পূর্ণ সালাম", "en": "The full greeting"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রহমাতুল্লাহি ওয়া বারাকাতুহ", "en": "As-salamu ''alaykum wa rahmatullahi wa barakatuh"}, "meaning": {"bn": "আপনার ওপর শান্তি, আল্লাহর রহমত ও তাঁর বরকত বর্ষিত হোক।", "en": "Peace be upon you, and the mercy of Allah and His blessings."}}, {"type": "text", "text": {"bn": "শুধু “আসসালামু আলাইকুম” বললে দশ নেকি, “ওয়া রহমাতুল্লাহ” যোগ করলে বিশ, আর “ওয়া বারাকাতুহ” যোগ করলে ত্রিশ নেকি।", "en": "Saying “As-salamu ''alaykum” earns ten good deeds, adding “wa rahmatullah” twenty, and adding “wa barakatuh” thirty."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; সুনান তিরমিজি", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi"}, "check": true}, {"type": "text", "text": {"bn": "আল্লাহর কাছে সবচেয়ে নিকটবর্তী সে, যে আগে সালাম দেয়।", "en": "The closest of people to Allah is the one who begins the greeting."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৫১৯৭", "en": "Sunan Abi Dawud 5197"}}, {"type": "heading", "text": {"bn": "হাসিমুখ", "en": "A smiling face"}}, {"type": "text", "text": {"bn": "তোমার ভাইয়ের সামনে তোমার হাসিমুখ সদকা।", "en": "Your smile in the face of your brother is charity."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ১৯৫৬", "en": "Jami'' at-Tirmidhi 1956"}}, {"type": "text", "text": {"bn": "কোনো ভালো কাজকে তুচ্ছ মনে কোরো না, এমনকি তোমার ভাইয়ের সঙ্গে হাসিমুখে দেখা করাও।", "en": "Do not belittle any good deed, even meeting your brother with a cheerful face."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬২৬", "en": "Sahih Muslim 2626"}}, {"type": "heading", "text": {"bn": "রাস্তা থেকে কষ্টদায়ক জিনিস সরানো", "en": "Removing harm from the road"}}, {"type": "text", "text": {"bn": "ঈমানের সত্তরের বেশি শাখা আছে; সর্বোচ্চটি “লা ইলাহা ইল্লাল্লাহ” বলা, আর সর্বনিম্নটি রাস্তা থেকে কষ্টদায়ক জিনিস সরানো। লজ্জাশীলতাও ঈমানের একটি শাখা।", "en": "Faith has seventy-odd branches; the highest is saying “La ilaha illallah” and the lowest is removing something harmful from the road. Modesty is also a branch of faith."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৫", "en": "Sahih Muslim 35"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আমি এক ব্যক্তিকে জান্নাতে ঘুরে বেড়াতে দেখেছি, শুধু এই কারণে যে সে রাস্তার মাঝখান থেকে একটি গাছ (কাঁটাযুক্ত ডাল) কেটে সরিয়েছিল, যা মানুষকে কষ্ট দিত।", "en": "I saw a man moving about in Paradise because of a tree he cut from the middle of the road that used to harm people."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৫২; সহিহ মুসলিম ১৯১৪", "en": "Sahih al-Bukhari 652; Sahih Muslim 1914"}}, {"type": "note", "tone": "tip", "text": {"bn": "আজকের জীবনে এর উদাহরণ: রাস্তায় কলার খোসা, কাচ বা ইট সরানো, ময়লা নির্দিষ্ট জায়গায় ফেলা, আর গাড়ি এমনভাবে না রাখা যাতে পথচারীর কষ্ট হয়।", "en": "Today this includes removing banana peels, glass or bricks from the road, putting rubbish in its place and not parking in a way that blocks pedestrians."}}]', 'in_review', 330 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fd75b63c-48ac-5303-996a-55ec55d75e43', id, 'fazilat-khabar-khawano', '{"bn": "মানুষকে খাবার খাওয়ানোর ফজিলত", "en": "Virtues of feeding people"}', '{"bn": "খাবার খাওয়ানো ইসলামের উত্তম কাজ; সালাম, খাবার ও রাতের নামাজে শান্তির সঙ্গে জান্নাত।", "en": "Feeding people is among the best acts of Islam; salam, food and night prayer lead to Paradise in peace."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ নেককারদের প্রশংসায় বলেন: “তারা আল্লাহর ভালোবাসায় মিসকিন, এতিম ও বন্দিকে খাবার খাওয়ায় (এবং বলে): আমরা কেবল আল্লাহর সন্তুষ্টির জন্য তোমাদের খাওয়াই; তোমাদের কাছে কোনো প্রতিদান বা কৃতজ্ঞতা চাই না।”", "en": "Allah praises the righteous: “They give food, despite love for it, to the poor, the orphan and the captive, (saying) we feed you only for the sake of Allah; we want from you no reward or thanks.”"}}, {"type": "ref", "text": {"bn": "সূরা দাহর ৭৬:৮–৯", "en": "Al-Insan 76:8–9"}}, {"type": "text", "text": {"bn": "ইসলামের উত্তম কাজ হলো খাবার খাওয়ানো এবং পরিচিত-অপরিচিত সবাইকে সালাম দেওয়া।", "en": "The best act in Islam is feeding people and greeting those you know and do not know."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২", "en": "Sahih al-Bukhari 12"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ মদিনায় এসে প্রথম যে কথাগুলো বলেছিলেন: হে লোকসকল, সালামের প্রসার ঘটাও, খাবার খাওয়াও, মানুষ যখন ঘুমিয়ে থাকে তখন নামাজ পড়ো, তাহলে শান্তির সঙ্গে জান্নাতে প্রবেশ করবে।", "en": "Among the first words of the Prophet ﷺ in Madinah: O people, spread salam, feed others, and pray at night while people sleep, and you will enter Paradise in peace."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২৪৮৫; সুনান ইবনে মাজাহ ১৩৩৪", "en": "Jami'' at-Tirmidhi 2485; Sunan Ibn Majah 1334"}}, {"type": "text", "text": {"bn": "ক্ষুধার্তকে খাবার দাও, রোগীকে দেখতে যাও এবং বন্দিকে মুক্ত করো।", "en": "Feed the hungry, visit the sick and free the captive."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৩৭৩", "en": "Sahih al-Bukhari 5373"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ আবু যর (রা.)-কে বলেছিলেন: তরকারি রান্না করলে ঝোল একটু বাড়িয়ে দাও এবং প্রতিবেশীর খোঁজ নাও।", "en": "The Prophet ﷺ told Abu Dharr (RA): when you cook a stew, add more water and look after your neighbours."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬২৫", "en": "Sahih Muslim 2625"}}, {"type": "text", "text": {"bn": "যে রোজাদারকে ইফতার করায়, সে রোজাদারের সমান সওয়াব পায়, অথচ রোজাদারের সওয়াব একটুও কমে না।", "en": "Whoever gives a fasting person food to break his fast earns the same reward without decreasing his."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৮০৭", "en": "Jami'' at-Tirmidhi 807"}}, {"type": "note", "tone": "tip", "text": {"bn": "দাওয়াতে শুধু ধনী আত্মীয়দের নয়, গরিবদেরও ডাকুন; শুধু ধনীদের দাওয়াত দেওয়া ওয়ালিমাকে রাসুল ﷺ সবচেয়ে মন্দ খাবার বলেছেন (সহিহ মুসলিম ১৪৩২)।", "en": "Invite the poor, not only wealthy relatives; the Prophet ﷺ called a wedding feast to which only the rich are invited the worst food (Sahih Muslim 1432)."}}]', 'in_review', 340 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'cba49f6b-1da9-5c57-8b67-db4313e63ef1', id, 'fazilat-sat-byabsa', '{"bn": "ব্যবসায় সততার ফজিলত", "en": "Virtues of honesty in trade"}', '{"bn": "সত্য বলা ও দোষ প্রকাশ করলে ব্যবসায় বরকত আসে; সৎ ও বিশ্বস্ত ব্যবসায়ী কিয়ামতে নবী, সিদ্দিক ও শহিদদের সঙ্গী।", "en": "Truthfulness and disclosing defects bring blessing to trade; the honest, trustworthy merchant will be with the prophets, the truthful and the martyrs."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “ধ্বংস তাদের জন্য যারা মাপে কম দেয়; যারা মানুষের কাছ থেকে নেওয়ার সময় পূর্ণ মাপে নেয়, আর তাদের মেপে বা ওজন করে দেওয়ার সময় কম দেয়।”", "en": "Allah says: “Woe to those who give less; who take full measure from people but give less when they measure or weigh for them.”"}}, {"type": "ref", "text": {"bn": "সূরা মুতাফফিফিন ৮৩:১–৩", "en": "Al-Mutaffifin 83:1–3"}}, {"type": "text", "text": {"bn": "ক্রেতা-বিক্রেতা আলাদা না হওয়া পর্যন্ত চুক্তি বাতিলের অধিকার রাখে; যদি তারা সত্য বলে ও (পণ্যের দোষ) স্পষ্ট করে, তাদের বেচাকেনায় বরকত দেওয়া হয়; আর যদি গোপন করে ও মিথ্যা বলে, তাদের বেচাকেনার বরকত মুছে দেওয়া হয়।", "en": "Buyer and seller may cancel until they part; if they are truthful and make things clear, their sale is blessed; if they conceal and lie, the blessing of their sale is erased."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৭৯; সহিহ মুসলিম ১৫৩২", "en": "Sahih al-Bukhari 2079; Sahih Muslim 1532"}}, {"type": "text", "text": {"bn": "আল্লাহ সেই ব্যক্তির ওপর রহম করুন, যে বিক্রির সময়, কেনার সময় এবং পাওনা চাওয়ার সময় নম্র থাকে।", "en": "May Allah have mercy on a man who is lenient when he sells, when he buys and when he asks for repayment."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৭৬", "en": "Sahih al-Bukhari 2076"}}, {"type": "text", "text": {"bn": "এক ব্যবসায়ী মানুষকে ঋণ দিত এবং কর্মচারীকে বলত, অভাবী কাউকে পেলে ছাড় দিয়ো, হয়তো আল্লাহ আমাদের ছাড় দেবেন। ফলে আল্লাহ তাকে ক্ষমা করে দিলেন।", "en": "A merchant used to lend to people and tell his servant: if you find someone in hardship, let him off, perhaps Allah will let us off. So Allah forgave him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৭৮; সহিহ মুসলিম ১৫৬২", "en": "Sahih al-Bukhari 2078; Sahih Muslim 1562"}}, {"type": "text", "text": {"bn": "সত্যবাদী ও বিশ্বস্ত ব্যবসায়ী (কিয়ামতের দিন) নবী, সিদ্দিক ও শহিদদের সঙ্গে থাকবে।", "en": "The truthful, trustworthy merchant will be with the prophets, the truthful and the martyrs."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ১২০৯", "en": "Jami'' at-Tirmidhi 1209"}}, {"type": "note", "tone": "info", "text": {"bn": "ইমাম তিরমিজি এই শেষ হাদিসটিকে হাসান বলেছেন; কিছু মুহাদ্দিস এর সনদকে দুর্বল বলেছেন, তবে অর্থটি অন্যান্য সহিহ দলিলের সঙ্গে সামঞ্জস্যপূর্ণ।", "en": "At-Tirmidhi graded this last hadith hasan; some scholars consider its chain weak, though its meaning agrees with other sahih evidence."}}, {"type": "note", "tone": "warn", "text": {"bn": "রাসুল ﷺ খাদ্যের স্তূপে হাত ঢুকিয়ে ভেজা অংশ পেয়ে বললেন: যে প্রতারণা করে, সে আমার দলভুক্ত নয় (সহিহ মুসলিম ১০২)।", "en": "The Prophet ﷺ put his hand into a pile of grain and found it wet inside, and said: whoever cheats is not of us (Sahih Muslim 102)."}}]', 'in_review', 350 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('6beb7843-1fd6-586f-8ef5-5e2ab461a0d9', 1, 'الرَّحْمٰنُ', '{"bn": "আর-রহমান", "en": "Ar-Rahman"}', '{"bn": "পরম দয়াময়", "en": "The Most Gracious"}', '{"bn": "যাঁর দয়া দুনিয়াতে সব সৃষ্টির জন্য বিস্তৃত। তাওবা ছাড়া কুরআনের প্রতিটি সূরার শুরুতে বিসমিল্লাহর মধ্যে এই নাম আছে।", "en": "The One whose mercy reaches all creation in this world. It is in the Basmalah that opens every surah except At-Tawbah."}', '{"bn": "সূরা ফাতিহা ১:৩", "en": "Al-Fatihah 1:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('73832d2e-7d94-5823-b9c5-716ac0ab4911', 2, 'الرَّحِيمُ', '{"bn": "আর-রহিম", "en": "Ar-Rahim"}', '{"bn": "অতিশয় দয়ালু", "en": "The Most Merciful"}', '{"bn": "যিনি বিশেষভাবে মুমিনদের প্রতি দয়া করেন। কুরআনে আছে: “আর তিনি মুমিনদের প্রতি পরম দয়ালু।”", "en": "The One who is especially merciful to the believers: “And He is ever Merciful to the believers.”"}', '{"bn": "সূরা আহযাব ৩৩:৪৩", "en": "Al-Ahzab 33:43"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('5b1c7ac6-89cc-56cc-accc-b474c8dece4c', 3, 'الْمَلِكُ', '{"bn": "আল-মালিক", "en": "Al-Malik"}', '{"bn": "মহাবাদশাহ, প্রকৃত অধিপতি", "en": "The King, the Sovereign"}', '{"bn": "সব রাজত্ব ও ক্ষমতার প্রকৃত মালিক তিনিই; দুনিয়ার সব রাজত্ব সাময়িক। “মহিমান্বিত আল্লাহ, যিনি প্রকৃত বাদশাহ।”", "en": "All true kingship belongs to Him; every worldly kingdom is temporary. “Exalted is Allah, the True King.”"}', '{"bn": "সূরা ত্বা-হা ২০:১১৪", "en": "Ta-Ha 20:114"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b3098450-bd91-57fa-8cdd-de4c03fa2c34', 4, 'الْقُدُّوسُ', '{"bn": "আল-কুদ্দুস", "en": "Al-Quddus"}', '{"bn": "পরম পবিত্র", "en": "The Most Holy"}', '{"bn": "সব দোষ-ত্রুটি ও অপূর্ণতা থেকে তিনি সম্পূর্ণ পবিত্র।", "en": "He is completely pure, free of every flaw and imperfection."}', '{"bn": "সূরা জুমুআ ৬২:১", "en": "Al-Jumu''ah 62:1"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1f385073-2079-5531-a1d4-c7adc78aa6df', 5, 'السَّلَامُ', '{"bn": "আস-সালাম", "en": "As-Salam"}', '{"bn": "শান্তিদাতা, সব ত্রুটিমুক্ত", "en": "The Source of Peace"}', '{"bn": "তিনি সব দোষ থেকে মুক্ত এবং বান্দাদের শান্তি ও নিরাপত্তা দেন। ফরজ নামাজের পর পড়া হয়: “আল্লাহুম্মা আনতাস সালাম, ওয়া মিনকাস সালাম” (সহিহ মুসলিম ৫৯১)।", "en": "He is free of all defects and grants peace and safety. After the obligatory prayer we say “Allahumma antas-salam wa minkas-salam” (Sahih Muslim 591)."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c4362efb-4a0e-5354-8860-2fcce4dc057c', 6, 'الْمُؤْمِنُ', '{"bn": "আল-মু''মিন", "en": "Al-Mu''min"}', '{"bn": "নিরাপত্তাদাতা, বিশ্বস্ত", "en": "The Giver of Security, the Faithful"}', '{"bn": "যিনি বান্দাদের ভয় থেকে নিরাপত্তা দেন এবং নিজের ওয়াদা ও রাসুলদের সত্যতা প্রমাণ করেন।", "en": "He gives His servants safety from fear and confirms the truth of His promise and His messengers."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c74fe3d6-d3f8-59ab-bcb4-c3a802da9c45', 7, 'الْمُهَيْمِنُ', '{"bn": "আল-মুহাইমিন", "en": "Al-Muhaymin"}', '{"bn": "রক্ষাকর্তা, সর্বতত্ত্বাবধায়ক", "en": "The Guardian, the Overseer"}', '{"bn": "যিনি সবকিছুর ওপর নজর রাখেন ও রক্ষা করেন; সবকিছু তাঁর নিয়ন্ত্রণে।", "en": "He watches over and protects everything; all things are under His control."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('94d980a9-cf73-506a-be8d-07b28300405e', 8, 'الْعَزِيزُ', '{"bn": "আল-আযীয", "en": "Al-''Aziz"}', '{"bn": "মহাপরাক্রমশালী", "en": "The Almighty"}', '{"bn": "তিনি এমন শক্তিমান যাঁকে কেউ পরাজিত করতে পারে না। কুরআনে প্রায়ই “আল-আযীযুল হাকীম” একসঙ্গে এসেছে।", "en": "He is mighty and can never be overcome. The Quran often pairs it with Al-Hakim: “the Almighty, the All-Wise.”"}', '{"bn": "সূরা আলে ইমরান ৩:৬", "en": "Al ''Imran 3:6"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b88a8c70-4847-51b3-8b1b-d908ff4c6075', 9, 'الْجَبَّارُ', '{"bn": "আল-জাব্বার", "en": "Al-Jabbar"}', '{"bn": "মহাপ্রতাপশালী, ক্ষতিপূরণকারী", "en": "The Compeller, the Restorer"}', '{"bn": "তাঁর ইচ্ছা সবার ওপর কার্যকর; আবার তিনিই ভাঙা হৃদয় জোড়া লাগান ও দুর্বলের অভাব পূরণ করেন।", "en": "His will prevails over all; and He mends broken hearts and makes up what the weak lack."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f2b197ad-e65a-5293-a4e4-b50492e2e626', 10, 'الْمُتَكَبِّرُ', '{"bn": "আল-মুতাকাব্বির", "en": "Al-Mutakabbir"}', '{"bn": "সর্বশ্রেষ্ঠত্বের অধিকারী", "en": "The Supreme in Greatness"}', '{"bn": "সব বড়ত্ব ও শ্রেষ্ঠত্ব কেবল তাঁরই প্রাপ্য; বান্দার জন্য অহংকার নিন্দনীয়।", "en": "All greatness belongs to Him alone; for a servant, arrogance is blameworthy."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e48feac5-8b18-58c6-aa65-1b72bf0663df', 11, 'الْخَالِقُ', '{"bn": "আল-খালিক", "en": "Al-Khaliq"}', '{"bn": "সৃষ্টিকর্তা", "en": "The Creator"}', '{"bn": "যিনি সবকিছু নির্ধারিত পরিমাপে অস্তিত্বে এনেছেন।", "en": "He brought everything into being in a measured, decreed way."}', '{"bn": "সূরা হাশর ৫৯:২৪", "en": "Al-Hashr 59:24"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ffda24ea-de41-51c8-a022-3e6c131af9c1', 12, 'الْبَارِئُ', '{"bn": "আল-বারি", "en": "Al-Bari''"}', '{"bn": "উদ্ভাবনকারী", "en": "The Originator, the Maker"}', '{"bn": "যিনি সৃষ্টিকে কোনো পূর্ব নমুনা ছাড়া, ত্রুটিমুক্তভাবে অস্তিত্ব দেন।", "en": "He brings creation into existence without any prior model and free of flaws."}', '{"bn": "সূরা হাশর ৫৯:২৪", "en": "Al-Hashr 59:24"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ec852e39-620f-5603-83fc-6569b2574a41', 13, 'الْمُصَوِّرُ', '{"bn": "আল-মুসাওয়ির", "en": "Al-Musawwir"}', '{"bn": "আকৃতিদাতা", "en": "The Fashioner of Forms"}', '{"bn": "যিনি প্রতিটি সৃষ্টিকে আলাদা রূপ দেন; মাতৃগর্ভে যেমন ইচ্ছা তেমন আকৃতি দেন (সূরা আলে ইমরান ৩:৬)।", "en": "He gives every creature its own form; He shapes us in the womb as He wills (Al ''Imran 3:6)."}', '{"bn": "সূরা হাশর ৫৯:২৪", "en": "Al-Hashr 59:24"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a9ab9834-8676-543e-9ec1-2236d17590b0', 14, 'الْغَفَّارُ', '{"bn": "আল-গাফ্ফার", "en": "Al-Ghaffar"}', '{"bn": "মহাক্ষমাশীল", "en": "The Ever-Forgiving"}', '{"bn": "যিনি বারবার ক্ষমা করেন। নূহ (আ.) বলেছিলেন: “তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি মহাক্ষমাশীল।”", "en": "He forgives again and again. Nuh (AS) said: “Ask forgiveness of your Lord; indeed He is ever Forgiving.”"}', '{"bn": "সূরা নূহ ৭১:১০", "en": "Nuh 71:10"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('16a0777d-b763-50c8-b507-9521edda723a', 15, 'الْقَهَّارُ', '{"bn": "আল-কাহ্হার", "en": "Al-Qahhar"}', '{"bn": "মহাপরাক্রান্ত, সবার ওপর বিজয়ী", "en": "The Subduer"}', '{"bn": "সব সৃষ্টি তাঁর ক্ষমতার অধীন। কিয়ামতের দিন ঘোষণা হবে: “আজ রাজত্ব কার? এক, মহাপরাক্রান্ত আল্লাহর।”", "en": "All creation is subject to His power. On the Last Day: “To whom belongs the kingdom today? To Allah, the One, the Prevailing.”"}', '{"bn": "সূরা গাফির ৪০:১৬", "en": "Ghafir 40:16"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ce70640f-d02f-5883-beb8-a4607099f798', 16, 'الْوَهَّابُ', '{"bn": "আল-ওয়াহ্হাব", "en": "Al-Wahhab"}', '{"bn": "মহাদাতা", "en": "The Bestower"}', '{"bn": "যিনি বিনিময় ছাড়াই অফুরন্ত দান করেন। মুমিনদের দোয়া: “নিশ্চয়ই আপনি মহাদাতা।”", "en": "He gives endlessly without asking anything in return. The believers pray: “Indeed, You are the Bestower.”"}', '{"bn": "সূরা আলে ইমরান ৩:৮", "en": "Al ''Imran 3:8"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('39dcf412-69c3-554c-9c22-49a693bdffa8', 17, 'الرَّزَّاقُ', '{"bn": "আর-রায্যাক", "en": "Ar-Razzaq"}', '{"bn": "রিজিকদাতা", "en": "The Provider"}', '{"bn": "সব সৃষ্টির রিজিক তাঁর হাতে; “নিশ্চয়ই আল্লাহই রিজিকদাতা, প্রবল শক্তিধর।”", "en": "The provision of all creation is in His hand: “Indeed, Allah is the Provider, the Firm Possessor of strength.”"}', '{"bn": "সূরা যারিয়াত ৫১:৫৮", "en": "Adh-Dhariyat 51:58"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c21c14a7-1832-5179-b290-b0afba268654', 18, 'الْفَتَّاحُ', '{"bn": "আল-ফাত্তাহ", "en": "Al-Fattah"}', '{"bn": "উন্মোচনকারী, মীমাংসাকারী", "en": "The Opener, the Judge"}', '{"bn": "যিনি রহমত ও রিজিকের দরজা খুলে দেন এবং বান্দাদের মাঝে ন্যায্য ফয়সালা করেন।", "en": "He opens the doors of mercy and provision and judges between His servants with truth."}', '{"bn": "সূরা সাবা ৩৪:২৬", "en": "Saba 34:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('3611a2e4-f6f9-5f8c-a433-84dd97e07531', 19, 'الْعَلِيمُ', '{"bn": "আল-আলীম", "en": "Al-''Alim"}', '{"bn": "সর্বজ্ঞ", "en": "The All-Knowing"}', '{"bn": "প্রকাশ্য-গোপন, অতীত-ভবিষ্যৎ সবকিছু তিনি জানেন। ফেরেশতারা বলেছিলেন: “নিশ্চয়ই আপনি সর্বজ্ঞ, প্রজ্ঞাময়।”", "en": "He knows the seen and unseen, past and future. The angels said: “Indeed, You are the All-Knowing, the All-Wise.”"}', '{"bn": "সূরা বাকারা ২:৩২", "en": "Al-Baqarah 2:32"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('bad379ab-b1f1-5848-b447-d37c1bacc147', 20, 'الْقَابِضُ', '{"bn": "আল-কাবিদ", "en": "Al-Qabid"}', '{"bn": "সংকোচনকারী", "en": "The Withholder"}', '{"bn": "যিনি নিজ প্রজ্ঞায় রিজিক ইত্যাদি সংকুচিত করেন। “আল্লাহই সংকুচিত করেন ও প্রশস্ত করেন”; তাই এই নাম আল-বাসিতের সঙ্গে মিলিয়ে বলা উত্তম।", "en": "He constricts provision by His wisdom. “Allah withholds and grants abundance,” so this name is best mentioned together with Al-Basit."}', '{"bn": "সূরা বাকারা ২:২৪৫", "en": "Al-Baqarah 2:245"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('099576f0-41ec-52bb-89c2-7a3bed3e6d76', 21, 'الْبَاسِطُ', '{"bn": "আল-বাসিত", "en": "Al-Basit"}', '{"bn": "প্রসারকারী", "en": "The Expander"}', '{"bn": "যিনি যাকে ইচ্ছা রিজিক ও অনুগ্রহ প্রশস্ত করে দেন।", "en": "He expands provision and favour for whom He wills."}', '{"bn": "সূরা বাকারা ২:২৪৫", "en": "Al-Baqarah 2:245"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('2be487ed-679c-574f-9e6f-ae329a058bc5', 22, 'الْخَافِضُ', '{"bn": "আল-খাফিদ", "en": "Al-Khafid"}', '{"bn": "অবনতকারী", "en": "The Abaser"}', '{"bn": "যিনি অহংকারী ও জালিমদের নিচু করেন। নামটি কুরআনে নাম হিসেবে আসেনি; সহিহ হাদিসে আছে, আল্লাহ দাঁড়িপাল্লা নিচু করেন ও উঁচু করেন (সহিহ মুসলিম ১৭৯)।", "en": "He lowers the arrogant and the oppressors. It does not occur in the Quran as a name; a sahih hadith says Allah lowers the scale and raises it (Sahih Muslim 179)."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f1f44131-3292-5962-9f54-4b771a61af4c', 23, 'الرَّافِعُ', '{"bn": "আর-রাফি", "en": "Ar-Rafi''"}', '{"bn": "উন্নীতকারী", "en": "The Exalter"}', '{"bn": "যিনি মর্যাদা উঁচু করেন; “তোমাদের মধ্যে যারা ঈমান এনেছে এবং যাদের জ্ঞান দেওয়া হয়েছে, আল্লাহ তাদের মর্যাদা উঁচু করবেন।”", "en": "He raises people in rank: “Allah will raise those who have believed among you and those given knowledge, by degrees.”"}', '{"bn": "সূরা মুজাদালা ৫৮:১১", "en": "Al-Mujadilah 58:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('00905c3b-1c1f-5614-ad81-5b90aea6b33f', 24, 'الْمُعِزُّ', '{"bn": "আল-মুইয্য", "en": "Al-Mu''izz"}', '{"bn": "সম্মানদাতা", "en": "The Giver of Honour"}', '{"bn": "সম্মান কেবল তাঁর হাতে; “আপনি যাকে ইচ্ছা সম্মান দেন।”", "en": "Honour is in His hand alone: “You honour whom You will.”"}', '{"bn": "সূরা আলে ইমরান ৩:২৬", "en": "Al ''Imran 3:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a72ff8d0-9982-5aea-ad63-68f655e41810', 25, 'الْمُذِلُّ', '{"bn": "আল-মুযিল্ল", "en": "Al-Mudhill"}', '{"bn": "অপমানকারী", "en": "The Giver of Disgrace"}', '{"bn": "তিনি যাকে ইচ্ছা ন্যায়সঙ্গতভাবে লাঞ্ছিত করেন; “আর যাকে ইচ্ছা অপমানিত করেন।” আল-মুইয্যের সঙ্গে মিলিয়ে বলা উত্তম।", "en": "He humbles whom He wills, justly: “and You humble whom You will.” Best mentioned together with Al-Mu''izz."}', '{"bn": "সূরা আলে ইমরান ৩:২৬", "en": "Al ''Imran 3:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e7087ef0-bb1c-5801-8f8d-3c39d062634d', 26, 'السَّمِيعُ', '{"bn": "আস-সামী", "en": "As-Sami''"}', '{"bn": "সর্বশ্রোতা", "en": "The All-Hearing"}', '{"bn": "সব আওয়াজ, এমনকি মনের নীরব দোয়াও তিনি শোনেন।", "en": "He hears every sound, even the silent prayer of the heart."}', '{"bn": "সূরা শূরা ৪২:১১", "en": "Ash-Shura 42:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ae5e7271-c5d6-56c4-b21f-2c5e91e0d0c5', 27, 'الْبَصِيرُ', '{"bn": "আল-বাসীর", "en": "Al-Basir"}', '{"bn": "সর্বদ্রষ্টা", "en": "The All-Seeing"}', '{"bn": "কোনো কিছুই তাঁর দৃষ্টির আড়ালে নয়; “তাঁর মতো কিছুই নেই, তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।”", "en": "Nothing is hidden from His sight: “There is nothing like Him, and He is the All-Hearing, the All-Seeing.”"}', '{"bn": "সূরা শূরা ৪২:১১", "en": "Ash-Shura 42:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('173543e4-5803-577b-8c4d-8f19ffae858c', 28, 'الْحَكَمُ', '{"bn": "আল-হাকাম", "en": "Al-Hakam"}', '{"bn": "মহাবিচারক", "en": "The Judge"}', '{"bn": "চূড়ান্ত ফয়সালা ও বিধান দেওয়ার অধিকার তাঁরই; “আমি কি আল্লাহ ছাড়া অন্য কাউকে বিচারক মানব?”", "en": "The final judgement and law belong to Him: “Shall I seek a judge other than Allah?”"}', '{"bn": "সূরা আনআম ৬:১১৪", "en": "Al-An''am 6:114"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('17dbabc9-731f-5308-b964-adc2272364c0', 29, 'الْعَدْلُ', '{"bn": "আল-আদল", "en": "Al-''Adl"}', '{"bn": "ন্যায়পরায়ণ", "en": "The Just"}', '{"bn": "তিনি কারও প্রতি বিন্দুমাত্র জুলুম করেন না। শব্দটি কুরআনে নাম হিসেবে নয়, গুণ হিসেবে এসেছে: “তোমার রবের বাণী সত্য ও ন্যায়ে পরিপূর্ণ।”", "en": "He never wrongs anyone in the least. The word occurs in the Quran as a quality, not a name: “The word of your Lord is complete in truth and justice.”"}', '{"bn": "সূরা আনআম ৬:১১৫", "en": "Al-An''am 6:115"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('8c081497-f091-520d-a177-48e2078b3057', 30, 'اللَّطِيفُ', '{"bn": "আল-লাতীফ", "en": "Al-Latif"}', '{"bn": "সূক্ষ্মদর্শী, কোমল দয়ালু", "en": "The Subtle, the Gentle"}', '{"bn": "যিনি অতি সূক্ষ্ম বিষয়ও জানেন এবং বান্দার প্রতি অদৃশ্যভাবে অনুগ্রহ করেন।", "en": "He knows the finest details and is kind to His servants in ways they do not see."}', '{"bn": "সূরা মুলক ৬৭:১৪", "en": "Al-Mulk 67:14"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e676e7e9-7aab-5087-bd35-1d06f3ff1a59', 31, 'الْخَبِيرُ', '{"bn": "আল-খাবীর", "en": "Al-Khabir"}', '{"bn": "সর্ববিষয়ে অবগত", "en": "The All-Aware"}', '{"bn": "সবকিছুর ভেতরের খবরও তিনি জানেন; “যিনি সৃষ্টি করেছেন তিনি কি জানবেন না? তিনি সূক্ষ্মদর্শী, সব বিষয়ে অবগত।”", "en": "He knows the inner reality of all things: “Does He not know, He who created, while He is the Subtle, the All-Aware?”"}', '{"bn": "সূরা মুলক ৬৭:১৪", "en": "Al-Mulk 67:14"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('31e75f15-7475-5834-b36d-eaa2a1ae7767', 32, 'الْحَلِيمُ', '{"bn": "আল-হালীম", "en": "Al-Halim"}', '{"bn": "সহনশীল", "en": "The Forbearing"}', '{"bn": "বান্দা অপরাধ করলেও তিনি সঙ্গে সঙ্গে শাস্তি দেন না, তওবার সুযোগ দেন।", "en": "Even when servants sin, He does not punish at once but gives time to repent."}', '{"bn": "সূরা বাকারা ২:২৬৩", "en": "Al-Baqarah 2:263"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('4978ea52-d4ce-5cc8-bb28-8b7f608ec8bc', 33, 'الْعَظِيمُ', '{"bn": "আল-আযীম", "en": "Al-''Azim"}', '{"bn": "মহান", "en": "The Magnificent"}', '{"bn": "সত্তা ও গুণে তিনি সর্বোচ্চ মহান; আয়াতুল কুরসি শেষ হয় “ওয়া হুওয়াল আলিয়্যুল আযীম” দিয়ে।", "en": "He is supremely great in Essence and attributes; Ayat al-Kursi ends with “and He is the Most High, the Magnificent.”"}', '{"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('4ecf54e1-06d5-5de3-a2f2-925c49960d0c', 34, 'الْغَفُورُ', '{"bn": "আল-গাফুর", "en": "Al-Ghafur"}', '{"bn": "অতি ক্ষমাশীল", "en": "The All-Forgiving"}', '{"bn": "যিনি বড় বড় গুনাহও ক্ষমা করেন; “আমার বান্দাদের জানিয়ে দাও, আমি অতি ক্ষমাশীল, পরম দয়ালু।”", "en": "He forgives even great sins: “Inform My servants that I am the Forgiving, the Merciful.”"}', '{"bn": "সূরা হিজর ১৫:৪৯", "en": "Al-Hijr 15:49"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b214a88a-5a51-569d-bc2c-87b21f9feee4', 35, 'الشَّكُورُ', '{"bn": "আশ-শাকুর", "en": "Ash-Shakur"}', '{"bn": "গুণগ্রাহী", "en": "The Appreciative"}', '{"bn": "বান্দার অল্প আমলকেও তিনি মূল্য দেন এবং বহুগুণ প্রতিদান দেন।", "en": "He values even a small deed of His servant and rewards it many times over."}', '{"bn": "সূরা তাগাবুন ৬৪:১৭", "en": "At-Taghabun 64:17"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('3823f923-9601-5216-937b-b39bd36e18c9', 36, 'الْعَلِيُّ', '{"bn": "আল-আলিয়্য", "en": "Al-''Aliyy"}', '{"bn": "সমুচ্চ", "en": "The Most High"}', '{"bn": "সত্তা, মর্যাদা ও ক্ষমতায় তিনি সবার ঊর্ধ্বে।", "en": "He is above all in Essence, rank and power."}', '{"bn": "সূরা হজ ২২:৬২", "en": "Al-Hajj 22:62"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('534b65fd-7cc9-5019-a3c8-f0cc37d6419f', 37, 'الْكَبِيرُ', '{"bn": "আল-কাবীর", "en": "Al-Kabir"}', '{"bn": "মহীয়ান, সর্বশ্রেষ্ঠ", "en": "The Most Great"}', '{"bn": "তাঁর চেয়ে বড় কিছু নেই; তাই আমরা “আল্লাহু আকবার” বলি।", "en": "Nothing is greater than Him; that is why we say “Allahu Akbar.”"}', '{"bn": "সূরা হজ ২২:৬২", "en": "Al-Hajj 22:62"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1b15524d-5df3-5dc4-be5e-8a872858857d', 38, 'الْحَفِيظُ', '{"bn": "আল-হাফীয", "en": "Al-Hafiz"}', '{"bn": "সংরক্ষণকারী", "en": "The Preserver"}', '{"bn": "যিনি সবকিছু রক্ষা করেন এবং বান্দার আমল সংরক্ষণ করেন; “নিশ্চয়ই আমার রব সবকিছুর রক্ষক।”", "en": "He guards all things and keeps record of deeds: “Indeed, my Lord is Guardian over all things.”"}', '{"bn": "সূরা হুদ ১১:৫৭", "en": "Hud 11:57"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('808e29d2-76c4-50f1-b2ee-2f5e3271ee8a', 39, 'الْمُقِيتُ', '{"bn": "আল-মুকীত", "en": "Al-Muqit"}', '{"bn": "আহার ও শক্তিদাতা", "en": "The Nourisher"}', '{"bn": "যিনি প্রতিটি প্রাণীর খাদ্য ও শক্তি জোগান এবং সবকিছুর ওপর ক্ষমতাবান।", "en": "He supplies every creature with food and strength and has power over all things."}', '{"bn": "সূরা নিসা ৪:৮৫", "en": "An-Nisa 4:85"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ca8df54b-5084-59ce-8ad7-957bed54e02d', 40, 'الْحَسِيبُ', '{"bn": "আল-হাসীব", "en": "Al-Hasib"}', '{"bn": "হিসাব গ্রহণকারী, যথেষ্ট", "en": "The Reckoner, the Sufficient"}', '{"bn": "যিনি বান্দার সব আমলের হিসাব নেবেন, আর যে তাঁর ওপর ভরসা করে তার জন্য তিনিই যথেষ্ট।", "en": "He will take account of every deed, and He is enough for whoever relies on Him."}', '{"bn": "সূরা নিসা ৪:৮৬", "en": "An-Nisa 4:86"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c20343e0-8636-594f-ab96-321595b9b9a6', 41, 'الْجَلِيلُ', '{"bn": "আল-জালীল", "en": "Al-Jalil"}', '{"bn": "মহিমান্বিত", "en": "The Majestic"}', '{"bn": "মহত্ত্ব ও মর্যাদার পূর্ণতা তাঁরই। নামটি এই রূপে কুরআনে নেই; তবে “যুল-জালাল” (মহিমার অধিকারী) রূপে এসেছে।", "en": "Perfect majesty is His. The name is not in the Quran in this form, but occurs as “Dhul-Jalal” (Owner of Majesty)."}', '{"bn": "সূরা আর-রহমান ৫৫:৭৮", "en": "Ar-Rahman 55:78"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('630a34e9-8046-5c8d-a37a-b4e162ed2e3a', 42, 'الْكَرِيمُ', '{"bn": "আল-কারীম", "en": "Al-Karim"}', '{"bn": "পরম দানশীল, মহাসম্মানিত", "en": "The Most Generous"}', '{"bn": "যিনি না চাইতেই দেন এবং অপরাধীকেও দয়া করেন; “হে মানুষ, কিসে তোমাকে তোমার মহান রব সম্পর্কে ধোঁকায় ফেলল?”", "en": "He gives without being asked and is kind even to wrongdoers: “O mankind, what has deceived you about your Lord, the Generous?”"}', '{"bn": "সূরা ইনফিতার ৮২:৬", "en": "Al-Infitar 82:6"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('05ddeee7-27c6-5515-93bf-25ce24b358e8', 43, 'الرَّقِيبُ', '{"bn": "আর-রাকীব", "en": "Ar-Raqib"}', '{"bn": "পর্যবেক্ষক", "en": "The Watchful"}', '{"bn": "তিনি সবসময় বান্দার প্রতিটি কাজ ও চিন্তা দেখছেন; “নিশ্চয়ই আল্লাহ তোমাদের ওপর সজাগ দৃষ্টি রাখেন।”", "en": "He constantly watches every deed and thought: “Indeed, Allah is ever, over you, an Observer.”"}', '{"bn": "সূরা নিসা ৪:১", "en": "An-Nisa 4:1"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f58cad78-de7f-575b-8811-353648306cfe', 44, 'الْمُجِيبُ', '{"bn": "আল-মুজীব", "en": "Al-Mujib"}', '{"bn": "দোয়া কবুলকারী", "en": "The Responsive"}', '{"bn": "যিনি বান্দার ডাকে সাড়া দেন; সালেহ (আ.) বলেছিলেন: “নিশ্চয়ই আমার রব নিকটে, ডাকে সাড়া দেন।”", "en": "He answers those who call on Him. Salih (AS) said: “Indeed, my Lord is near and responsive.”"}', '{"bn": "সূরা হুদ ১১:৬১", "en": "Hud 11:61"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('6fb270b4-b483-59d7-b8c2-27e94cfb8519', 45, 'الْوَاسِعُ', '{"bn": "আল-ওয়াসি", "en": "Al-Wasi''"}', '{"bn": "সর্বব্যাপী, প্রাচুর্যময়", "en": "The All-Encompassing"}', '{"bn": "তাঁর জ্ঞান, রহমত ও দান সবকিছুকে পরিব্যাপ্ত করে আছে।", "en": "His knowledge, mercy and giving encompass everything."}', '{"bn": "সূরা বাকারা ২:১১৫", "en": "Al-Baqarah 2:115"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('28c464db-8ba1-54a9-a6e3-4e013bc61841', 46, 'الْحَكِيمُ', '{"bn": "আল-হাকীম", "en": "Al-Hakim"}', '{"bn": "প্রজ্ঞাময়", "en": "The All-Wise"}', '{"bn": "তাঁর প্রতিটি আদেশ ও সিদ্ধান্তে গভীর প্রজ্ঞা আছে, যদিও আমরা সব সময় তা বুঝি না।", "en": "There is deep wisdom in each of His commands and decrees, even when we do not see it."}', '{"bn": "সূরা আনআম ৬:১৮", "en": "Al-An''am 6:18"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c26398db-1c0d-5e2b-b005-ba7f2dd562e6', 47, 'الْوَدُودُ', '{"bn": "আল-ওয়াদুদ", "en": "Al-Wadud"}', '{"bn": "প্রেমময়", "en": "The Most Loving"}', '{"bn": "যিনি মুমিনদের ভালোবাসেন এবং মুমিনরাও যাঁকে ভালোবাসে; “তিনি ক্ষমাশীল, প্রেমময়।”", "en": "He loves the believers and is loved by them: “And He is the Forgiving, the Loving.”"}', '{"bn": "সূরা বুরুজ ৮৫:১৪", "en": "Al-Buruj 85:14"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('cf1d8af6-3907-5136-85a8-5d4161c2dd5a', 48, 'الْمَجِيدُ', '{"bn": "আল-মাজীদ", "en": "Al-Majid"}', '{"bn": "মহাগৌরবময়", "en": "The Most Glorious"}', '{"bn": "মর্যাদা ও দানে তিনি অতি গৌরবময়; দরুদে ইবরাহিমি শেষ হয় “ইন্নাকা হামীদুম মাজীদ” দিয়ে।", "en": "He is most glorious in honour and generosity; the Ibrahimi durood ends with “innaka Hamidun Majid.”"}', '{"bn": "সূরা হুদ ১১:৭৩", "en": "Hud 11:73"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('8ce23d91-65db-5536-9b2d-bc989a95ed6b', 49, 'الْبَاعِثُ', '{"bn": "আল-বা''ইস", "en": "Al-Ba''ith"}', '{"bn": "পুনরুত্থানকারী", "en": "The Resurrector"}', '{"bn": "যিনি রাসুল পাঠিয়েছেন এবং মৃতদের কবর থেকে আবার জীবিত করে উঠাবেন; “আল্লাহ কবরবাসীদের পুনরুত্থিত করবেন।”", "en": "He sent the messengers and will raise the dead from their graves: “Allah will resurrect those in the graves.”"}', '{"bn": "সূরা হজ ২২:৭", "en": "Al-Hajj 22:7"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('612e0290-68e6-5446-a8ba-d9bec61807cc', 50, 'الشَّهِيدُ', '{"bn": "আশ-শাহীদ", "en": "Ash-Shahid"}', '{"bn": "সাক্ষী, সর্বপ্রত্যক্ষকারী", "en": "The Witness"}', '{"bn": "সবকিছু তাঁর সামনে উপস্থিত; “নিশ্চয়ই আল্লাহ সবকিছুর সাক্ষী।”", "en": "Everything is present before Him: “Indeed, Allah is Witness over all things.”"}', '{"bn": "সূরা হজ ২২:১৭", "en": "Al-Hajj 22:17"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a20a94b3-f6c4-573f-9890-fb855e3020e8', 51, 'الْحَقُّ', '{"bn": "আল-হাক্ক", "en": "Al-Haqq"}', '{"bn": "চিরসত্য", "en": "The Truth"}', '{"bn": "তাঁর অস্তিত্ব, কথা ও ওয়াদা সবই সত্য; “তারা জানবে যে আল্লাহই সুস্পষ্ট সত্য।”", "en": "His existence, word and promise are all true: “They will know that Allah is the manifest Truth.”"}', '{"bn": "সূরা নূর ২৪:২৫", "en": "An-Nur 24:25"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('156f3eb8-e962-5543-9257-6ea61e3b9869', 52, 'الْوَكِيلُ', '{"bn": "আল-ওয়াকীল", "en": "Al-Wakil"}', '{"bn": "কর্মবিধায়ক, ভরসাস্থল", "en": "The Trustee"}', '{"bn": "যাঁর ওপর ভরসা করলে তিনিই যথেষ্ট; বিপদে মুমিনরা বলেছিলেন: “হাসবুনাল্লাহু ওয়া নি''মাল ওয়াকীল।”", "en": "He is enough for whoever trusts Him; in danger the believers said: “Allah is sufficient for us, and He is the best Trustee.”"}', '{"bn": "সূরা আলে ইমরান ৩:১৭৩", "en": "Al ''Imran 3:173"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a00dff7a-1529-5d92-b1b3-c9cda7e3f3f8', 53, 'الْقَوِيُّ', '{"bn": "আল-কাবিয়্য", "en": "Al-Qawiyy"}', '{"bn": "মহাশক্তিমান", "en": "The All-Strong"}', '{"bn": "তাঁর শক্তির কোনো সীমা নেই, তিনি কখনো দুর্বল হন না।", "en": "His strength has no limit; He never weakens."}', '{"bn": "সূরা শূরা ৪২:১৯", "en": "Ash-Shura 42:19"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f9fac01f-9bbf-51bb-9722-6d0262c0f470', 54, 'الْمَتِينُ', '{"bn": "আল-মাতীন", "en": "Al-Matin"}', '{"bn": "সুদৃঢ়", "en": "The Firm"}', '{"bn": "যাঁর শক্তি অটল ও সুদৃঢ়; কোনো কাজে তিনি ক্লান্ত হন না।", "en": "His strength is firm and unshakable; no task tires Him."}', '{"bn": "সূরা যারিয়াত ৫১:৫৮", "en": "Adh-Dhariyat 51:58"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('38eedc9c-f2ec-58ad-a06e-45d971921b97', 55, 'الْوَلِيُّ', '{"bn": "আল-ওয়ালিয়্য", "en": "Al-Waliyy"}', '{"bn": "অভিভাবক, বন্ধু", "en": "The Protecting Friend"}', '{"bn": "তিনি মুমিনদের অভিভাবক; “আল্লাহ মুমিনদের অভিভাবক, তিনি তাদের অন্ধকার থেকে আলোর দিকে বের করে আনেন।”", "en": "He is the ally of the believers: “Allah is the ally of those who believe; He brings them out of darkness into light.”"}', '{"bn": "সূরা বাকারা ২:২৫৭", "en": "Al-Baqarah 2:257"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('07936025-bc65-5722-8dc8-438d245f7990', 56, 'الْحَمِيدُ', '{"bn": "আল-হামীদ", "en": "Al-Hamid"}', '{"bn": "প্রশংসিত", "en": "The Praiseworthy"}', '{"bn": "সব অবস্থায় সব প্রশংসা তাঁরই প্রাপ্য; “আল্লাহই অভাবমুক্ত, প্রশংসিত।”", "en": "All praise in every state is His due: “Allah is the Free of need, the Praiseworthy.”"}', '{"bn": "সূরা ফাতির ৩৫:১৫", "en": "Fatir 35:15"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('25ed88bb-5ee4-5394-8a1e-e38da3a603e8', 57, 'الْمُحْصِي', '{"bn": "আল-মুহসী", "en": "Al-Muhsi"}', '{"bn": "সবকিছু গণনাকারী", "en": "The Accounter"}', '{"bn": "যিনি সবকিছু গুনে রেখেছেন; “তিনি তাদের পরিবেষ্টন করে রেখেছেন এবং গুনে গুনে হিসাব রেখেছেন।”", "en": "He has counted everything: “He has enumerated them and counted them a full counting.”"}', '{"bn": "সূরা মারইয়াম ১৯:৯৪", "en": "Maryam 19:94"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('99f5ce49-4227-515d-8408-070d7c884c5e', 58, 'الْمُبْدِئُ', '{"bn": "আল-মুবদি", "en": "Al-Mubdi''"}', '{"bn": "প্রথমবার সৃষ্টিকারী", "en": "The Originator"}', '{"bn": "যিনি সৃষ্টিকে প্রথমবার অস্তিত্বে এনেছেন; “তিনিই প্রথমবার সৃষ্টি করেন এবং পুনরায় করবেন।”", "en": "He brought creation into being the first time: “It is He who originates and repeats.”"}', '{"bn": "সূরা বুরুজ ৮৫:১৩", "en": "Al-Buruj 85:13"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('af51131e-4e46-5e2c-a11f-e0ab6fbd246c', 59, 'الْمُعِيدُ', '{"bn": "আল-মুঈদ", "en": "Al-Mu''id"}', '{"bn": "পুনরায় সৃষ্টিকারী", "en": "The Restorer"}', '{"bn": "যিনি মৃত্যুর পর সৃষ্টিকে আবার জীবিত করবেন।", "en": "He will bring creation back to life after death."}', '{"bn": "সূরা বুরুজ ৮৫:১৩", "en": "Al-Buruj 85:13"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ec816b91-340d-5a53-8a4d-63f8ffa9b93a', 60, 'الْمُحْيِي', '{"bn": "আল-মুহয়ী", "en": "Al-Muhyi"}', '{"bn": "জীবনদাতা", "en": "The Giver of Life"}', '{"bn": "যিনি মৃত মাটিকে জীবিত করেন; “নিশ্চয়ই তিনিই মৃতদের জীবনদাতা।”", "en": "He revives dead land: “Indeed, that same One will give life to the dead.”"}', '{"bn": "সূরা রুম ৩০:৫০", "en": "Ar-Rum 30:50"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1b16e82f-0439-5e43-8812-653963e2c7b4', 61, 'الْمُمِيتُ', '{"bn": "আল-মুমীত", "en": "Al-Mumit"}', '{"bn": "মৃত্যুদাতা", "en": "The Bringer of Death"}', '{"bn": "প্রতিটি প্রাণের মৃত্যু তাঁর নির্ধারিত সময়েই আসে; “তিনিই জীবন দেন ও মৃত্যু দেন।”", "en": "Every soul dies at the time He has set: “He gives life and causes death.”"}', '{"bn": "সূরা হাদিদ ৫৭:২", "en": "Al-Hadid 57:2"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c5fd459c-6575-59d3-aafb-5de204d88c21', 62, 'الْحَيُّ', '{"bn": "আল-হাইয়্য", "en": "Al-Hayy"}', '{"bn": "চিরঞ্জীব", "en": "The Ever-Living"}', '{"bn": "যাঁর জীবনের শুরু ও শেষ নেই; “ভরসা করো সেই চিরঞ্জীবের ওপর, যিনি কখনো মরবেন না।”", "en": "His life has no beginning or end: “Rely upon the Ever-Living who does not die.”"}', '{"bn": "সূরা ফুরকান ২৫:৫৮", "en": "Al-Furqan 25:58"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('52cd2210-5dc4-5e4a-9f97-155ea2bf2220', 63, 'الْقَيُّومُ', '{"bn": "আল-কাইয়ুম", "en": "Al-Qayyum"}', '{"bn": "চিরস্থায়ী, সবকিছুর ধারক", "en": "The Self-Sustaining"}', '{"bn": "তিনি কারও মুখাপেক্ষী নন, আর সবকিছু তাঁরই ওপর নির্ভর করে টিকে আছে; আয়াতুল কুরসিতে নামটি আছে।", "en": "He depends on none, while all things depend on Him for their existence; it occurs in Ayat al-Kursi."}', '{"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('65037622-4c46-5721-8ce1-a7e57b3c73e8', 64, 'الْوَاجِدُ', '{"bn": "আল-ওয়াজিদ", "en": "Al-Wajid"}', '{"bn": "অভাবমুক্ত, যিনি যা চান পান", "en": "The Finder, the Self-Sufficient"}', '{"bn": "তাঁর কোনো কিছুর অভাব নেই; যা ইচ্ছা করেন তা-ই পান। এই নামটি কুরআনে আসেনি, তিরমিজির তালিকায় আছে।", "en": "He lacks nothing and finds whatever He wills. This name does not occur in the Quran; it is in Tirmidhi''s list."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('52584c10-2804-5b83-a52d-02c7ac99ef62', 65, 'الْمَاجِدُ', '{"bn": "আল-মাজিদ", "en": "Al-Maajid"}', '{"bn": "মহিমান্বিত, মর্যাদাবান", "en": "The Noble, the Illustrious"}', '{"bn": "মর্যাদা ও দানশীলতায় পরিপূর্ণ; অর্থে আল-মাজীদের কাছাকাছি। এই রূপটি কুরআনে আসেনি।", "en": "Full of honour and generosity; close in meaning to Al-Majid. This form does not occur in the Quran."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('929b26a4-a8fc-5a13-a96b-e92d1077d390', 66, 'الْوَاحِدُ', '{"bn": "আল-ওয়াহিদ", "en": "Al-Wahid"}', '{"bn": "এক, একক", "en": "The One"}', '{"bn": "সত্তা ও গুণে তিনি এক, তাঁর কোনো শরিক নেই; “তিনি এক, মহাপরাক্রান্ত।”", "en": "He is One in Essence and attributes, without partner: “He is the One, the Prevailing.”"}', '{"bn": "সূরা রা''দ ১৩:১৬", "en": "Ar-Ra''d 13:16"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('dd97d7a3-2ad6-5715-886b-55a7ba64e319', 67, 'الْأَحَدُ', '{"bn": "আল-আহাদ", "en": "Al-Ahad"}', '{"bn": "অদ্বিতীয়", "en": "The Unique, the Only One"}', '{"bn": "যাঁর মতো আর কেউ নেই; সূরা ইখলাস শুরু হয় “কুল হুওয়াল্লাহু আহাদ” দিয়ে। তিরমিজির কিছু সংস্করণে এই নামটি নেই।", "en": "There is none like Him; Surah Al-Ikhlas begins “Say: He is Allah, the One.” Some editions of Tirmidhi''s list do not include it."}', '{"bn": "সূরা ইখলাস ১১২:১", "en": "Al-Ikhlas 112:1"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ccb75737-309d-529f-b6f5-49d61bd74741', 68, 'الصَّمَدُ', '{"bn": "আস-সামাদ", "en": "As-Samad"}', '{"bn": "অমুখাপেক্ষী, সবার আশ্রয়স্থল", "en": "The Eternal Refuge"}', '{"bn": "সবাই তাঁর মুখাপেক্ষী, কিন্তু তিনি কারও মুখাপেক্ষী নন।", "en": "All depend on Him, while He depends on none."}', '{"bn": "সূরা ইখলাস ১১২:২", "en": "Al-Ikhlas 112:2"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('4955c80a-7893-593d-921f-b96c6c73278d', 69, 'الْقَادِرُ', '{"bn": "আল-কাদির", "en": "Al-Qadir"}', '{"bn": "সর্বশক্তিমান", "en": "The All-Capable"}', '{"bn": "যা ইচ্ছা তা করতে তিনি সক্ষম; “বলো, তিনি তোমাদের ওপর শাস্তি পাঠাতে সক্ষম।”", "en": "He is able to do whatever He wills: “Say: He is able to send upon you punishment.”"}', '{"bn": "সূরা আনআম ৬:৬৫", "en": "Al-An''am 6:65"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('527749d8-3ba4-5aa9-ac91-448c546b5c13', 70, 'الْمُقْتَدِرُ', '{"bn": "আল-মুকতাদির", "en": "Al-Muqtadir"}', '{"bn": "পূর্ণ ক্ষমতাবান", "en": "The All-Powerful"}', '{"bn": "যাঁর ক্ষমতা পরিপূর্ণ; মুত্তাকিরা থাকবে “সর্বশক্তিমান অধিপতির সান্নিধ্যে।”", "en": "His power is complete; the righteous will be “in the presence of a Sovereign, Perfect in Ability.”"}', '{"bn": "সূরা কামার ৫৪:৫৫", "en": "Al-Qamar 54:55"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('0164d77c-2df7-54ad-9d58-cf4fcbecbc66', 71, 'الْمُقَدِّمُ', '{"bn": "আল-মুকাদ্দিম", "en": "Al-Muqaddim"}', '{"bn": "অগ্রসরকারী", "en": "The Expediter"}', '{"bn": "যিনি যাকে ইচ্ছা ও যা ইচ্ছা আগে নিয়ে আসেন। রাসুল ﷺ রাতের নামাজের দোয়ায় বলতেন: “আনতাল মুকাদ্দিমু ওয়া আনতাল মুআখখির” (সহিহ বুখারি ও মুসলিম)।", "en": "He brings forward whom and what He wills. The Prophet ﷺ said in his night-prayer dua: “You are the One who brings forward and the One who delays” (Bukhari and Muslim)."}', '{"bn": "সূরা কাফ ৫০:২৮", "en": "Qaf 50:28"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ff5cb5b1-bc8c-5f47-bed3-05f37bd4b7c6', 72, 'الْمُؤَخِّرُ', '{"bn": "আল-মুআখখির", "en": "Al-Mu''akhkhir"}', '{"bn": "বিলম্বকারী", "en": "The Delayer"}', '{"bn": "যিনি নিজ প্রজ্ঞায় যা ইচ্ছা পিছিয়ে দেন; তিনি মানুষকে নির্দিষ্ট সময় পর্যন্ত অবকাশ দেন।", "en": "He delays what He wills by His wisdom; He gives people respite until an appointed time."}', '{"bn": "সূরা নাহল ১৬:৬১", "en": "An-Nahl 16:61"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e51acc55-e469-56a4-a85a-5bd95f3ce946', 73, 'الْأَوَّلُ', '{"bn": "আল-আওয়াল", "en": "Al-Awwal"}', '{"bn": "আদি, সর্বপ্রথম", "en": "The First"}', '{"bn": "যাঁর আগে কিছুই ছিল না; রাসুল ﷺ এভাবেই নামটি ব্যাখ্যা করেছেন (সহিহ মুসলিম ২৭১৩)।", "en": "There was nothing before Him; this is how the Prophet ﷺ explained it (Sahih Muslim 2713)."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('85e4da60-cdfa-5c2a-9459-b6b203489ea0', 74, 'الْآخِرُ', '{"bn": "আল-আখির", "en": "Al-Akhir"}', '{"bn": "অন্ত, সর্বশেষ", "en": "The Last"}', '{"bn": "যাঁর পরে কিছু নেই; সবকিছু শেষ হয়ে যাবে, তিনি থাকবেন।", "en": "There is nothing after Him; all will end and He will remain."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('389363fb-6df2-5485-a9b7-363c5399b3d8', 75, 'الظَّاهِرُ', '{"bn": "আয-যাহির", "en": "Az-Zahir"}', '{"bn": "প্রকাশ্য, সবার ঊর্ধ্বে", "en": "The Manifest"}', '{"bn": "যাঁর ঊর্ধ্বে কিছু নেই; তাঁর নিদর্শন সবখানে স্পষ্ট।", "en": "There is nothing above Him; His signs are clear everywhere."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('70ea66f2-0333-571b-94c5-4d9d64ff1c37', 76, 'الْبَاطِنُ', '{"bn": "আল-বাতিন", "en": "Al-Batin"}', '{"bn": "গোপন, অন্তর্নিহিত", "en": "The Hidden"}', '{"bn": "যাঁর চেয়ে নিকটে কিছু নেই, অথচ চোখ তাঁকে দেখতে পায় না।", "en": "Nothing is nearer than Him, yet eyes cannot perceive Him."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fbd3b3d6-2e7e-552a-9d43-fb52cfb89a2b', 77, 'الْوَالِي', '{"bn": "আল-ওয়ালী", "en": "Al-Wali"}', '{"bn": "সবকিছুর পরিচালক", "en": "The Governor"}', '{"bn": "যিনি সবকিছুর কাজ পরিচালনা করেন; “তিনি ছাড়া তাদের আর কোনো অভিভাবক নেই।”", "en": "He manages the affairs of all things: “There is not for them besides Him any patron.”"}', '{"bn": "সূরা রা''দ ১৩:১১", "en": "Ar-Ra''d 13:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1f5bf4ab-1c10-541f-b808-6a774c8669e1', 78, 'الْمُتَعَالِي', '{"bn": "আল-মুতাআলী", "en": "Al-Muta''ali"}', '{"bn": "সর্বোচ্চ মহিমান্বিত", "en": "The Most Exalted"}', '{"bn": "সব সৃষ্টির ঊর্ধ্বে এবং সব অপূর্ণতা থেকে বহু ঊর্ধ্বে; “তিনি মহান, সর্বোচ্চ।”", "en": "Above all creation and far above every imperfection: “the Grand, the Exalted.”"}', '{"bn": "সূরা রা''দ ১৩:৯", "en": "Ar-Ra''d 13:9"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('debbadc7-306b-530e-b360-2ff14eb651f1', 79, 'الْبَرُّ', '{"bn": "আল-বার্র", "en": "Al-Barr"}', '{"bn": "পরম কল্যাণকারী", "en": "The Source of Goodness"}', '{"bn": "যিনি বান্দাদের প্রতি অশেষ সদয়; “নিশ্চয়ই তিনি কল্যাণময়, পরম দয়ালু।”", "en": "He is endlessly good to His servants: “Indeed, it is He who is the Beneficent, the Merciful.”"}', '{"bn": "সূরা তূর ৫২:২৮", "en": "At-Tur 52:28"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ebc8ba32-f7a8-5aca-a1dc-a7ea05f0d8bd', 80, 'التَّوَّابُ', '{"bn": "আত-তাওয়াব", "en": "At-Tawwab"}', '{"bn": "তওবা কবুলকারী", "en": "The Accepter of Repentance"}', '{"bn": "যিনি বারবার তওবা কবুল করেন; আদম (আ.)-এর তওবাও তিনি কবুল করেছিলেন।", "en": "He accepts repentance again and again; He accepted the repentance of Adam (AS)."}', '{"bn": "সূরা বাকারা ২:৩৭", "en": "Al-Baqarah 2:37"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fb28cb60-c7a2-58ed-80ed-5fd6bd1db95a', 81, 'الْمُنْتَقِمُ', '{"bn": "আল-মুনতাকিম", "en": "Al-Muntaqim"}', '{"bn": "প্রতিশোধ গ্রহণকারী", "en": "The Avenger"}', '{"bn": "যিনি অবাধ্য অপরাধীদের ন্যায্য শাস্তি দেন; কুরআনে আছে: “আমি অপরাধীদের থেকে প্রতিশোধ নেব।”", "en": "He justly punishes persistent criminals: “Indeed, We will take retribution from the criminals.”"}', '{"bn": "সূরা সাজদা ৩২:২২", "en": "As-Sajdah 32:22"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('d9ddb9dd-7d30-5174-b0aa-f9fb15376eec', 82, 'الْعَفُوُّ', '{"bn": "আল-আফুউ", "en": "Al-''Afuww"}', '{"bn": "মার্জনাকারী", "en": "The Pardoner"}', '{"bn": "যিনি গুনাহ এমনভাবে মুছে দেন যেন চিহ্নও না থাকে; লাইলাতুল কদরের দোয়ায় এই নাম আছে (সুনান তিরমিজি ৩৫১৩)।", "en": "He erases sins as if they never were; this name is in the dua for Laylat al-Qadr (Jami'' at-Tirmidhi 3513)."}', '{"bn": "সূরা নিসা ৪:৪৩", "en": "An-Nisa 4:43"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fd0123e6-3550-57de-bdd0-ae66cc78a37b', 83, 'الرَّءُوفُ', '{"bn": "আর-রাউফ", "en": "Ar-Ra''uf"}', '{"bn": "অতি স্নেহশীল", "en": "The Most Kind"}', '{"bn": "যাঁর দয়া অত্যন্ত কোমল ও গভীর; “নিশ্চয়ই আল্লাহ মানুষের প্রতি অতি স্নেহশীল, পরম দয়ালু।”", "en": "His mercy is most tender: “Indeed, Allah is, to the people, Kind and Merciful.”"}', '{"bn": "সূরা বাকারা ২:১৪৩", "en": "Al-Baqarah 2:143"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('54e08c82-6dce-5744-b63b-bc4ca5421973', 84, 'مَالِكُ الْمُلْكِ', '{"bn": "মালিকুল মুলক", "en": "Malik al-Mulk"}', '{"bn": "সার্বভৌম ক্ষমতার মালিক", "en": "Owner of All Sovereignty"}', '{"bn": "তিনি যাকে ইচ্ছা রাজত্ব দেন, যার থেকে ইচ্ছা কেড়ে নেন; “বলো, হে আল্লাহ, রাজত্বের মালিক।”", "en": "He gives kingship to whom He wills and takes it from whom He wills: “Say: O Allah, Owner of Sovereignty.”"}', '{"bn": "সূরা আলে ইমরান ৩:২৬", "en": "Al ''Imran 3:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('76c5db6b-4cdf-5e08-bff5-8544ea73267f', 85, 'ذُو الْجَلَالِ وَالْإِكْرَامِ', '{"bn": "যুল-জালালি ওয়াল-ইকরাম", "en": "Dhul-Jalali wal-Ikram"}', '{"bn": "মহিমা ও সম্মানের অধিকারী", "en": "Lord of Majesty and Honour"}', '{"bn": "সব সৃষ্টি ধ্বংস হবে, কেবল মহিমা ও সম্মানের অধিকারী রবের চেহারা বাকি থাকবে।", "en": "All creation will perish, and only the Face of your Lord, Owner of Majesty and Honour, will remain."}', '{"bn": "সূরা আর-রহমান ৫৫:২৭", "en": "Ar-Rahman 55:27"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fe420444-ae03-5586-8720-a50f6959b702', 86, 'الْمُقْسِطُ', '{"bn": "আল-মুকসিত", "en": "Al-Muqsit"}', '{"bn": "ন্যায়বিচারক", "en": "The Equitable"}', '{"bn": "যিনি পূর্ণ ন্যায়ের সঙ্গে বিচার করেন; আল্লাহ নিজেই সাক্ষ্য দিয়েছেন যে তিনি ন্যায়ের সঙ্গে প্রতিষ্ঠিত।", "en": "He judges with perfect fairness; Allah Himself bears witness that He maintains justice."}', '{"bn": "সূরা আলে ইমরান ৩:১৮", "en": "Al ''Imran 3:18"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('9331779e-0191-50d7-adc0-1f0a8161441a', 87, 'الْجَامِعُ', '{"bn": "আল-জামি", "en": "Al-Jami''"}', '{"bn": "একত্রকারী", "en": "The Gatherer"}', '{"bn": "যিনি কিয়ামতের দিন সব মানুষকে একত্র করবেন; “হে আমাদের রব, আপনি মানুষকে এমন দিনে একত্র করবেন যাতে কোনো সন্দেহ নেই।”", "en": "He will gather all people on the Last Day: “Our Lord, You will gather the people for a Day about which there is no doubt.”"}', '{"bn": "সূরা আলে ইমরান ৩:৯", "en": "Al ''Imran 3:9"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f2fa5830-7c45-50f5-8774-a6259055771a', 88, 'الْغَنِيُّ', '{"bn": "আল-গানিয়্য", "en": "Al-Ghaniyy"}', '{"bn": "অভাবমুক্ত", "en": "The Self-Sufficient"}', '{"bn": "তিনি কারও মুখাপেক্ষী নন, আর সবাই তাঁর মুখাপেক্ষী; “আল্লাহ অভাবমুক্ত, আর তোমরা অভাবী।”", "en": "He needs no one, while all need Him: “Allah is the Free of need, and you are the needy.”"}', '{"bn": "সূরা মুহাম্মাদ ৪৭:৩৮", "en": "Muhammad 47:38"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('2bf680bb-c7a8-5b29-ad79-2accb16064b0', 89, 'الْمُغْنِي', '{"bn": "আল-মুগনী", "en": "Al-Mughni"}', '{"bn": "অভাব মোচনকারী", "en": "The Enricher"}', '{"bn": "যিনি বান্দাকে অভাবমুক্ত ও সচ্ছল করেন; “তিনিই ধনী করেন ও সম্পদ দান করেন।”", "en": "He frees His servants from need: “It is He who enriches and suffices.”"}', '{"bn": "সূরা নাজম ৫৩:৪৮", "en": "An-Najm 53:48"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('034249ed-d8d0-5a86-955a-9f13ca529e1e', 90, 'الْمَانِعُ', '{"bn": "আল-মানি", "en": "Al-Mani''"}', '{"bn": "প্রতিরোধকারী", "en": "The Preventer"}', '{"bn": "তিনি যা আটকে রাখেন কেউ তা দিতে পারে না; নামাজের পর দোয়ায় আছে: “আপনি যা আটকান তা দেওয়ার কেউ নেই” (সহিহ বুখারি ৮৪৪)। এই নামটি কুরআনে আসেনি।", "en": "None can give what He withholds; after prayer we say “none can give what You withhold” (Sahih al-Bukhari 844). This name does not occur in the Quran."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('d7375886-8fc3-5c7f-9b7a-85133b7114f5', 91, 'الضَّارُّ', '{"bn": "আদ-দার্র", "en": "Ad-Darr"}', '{"bn": "ক্ষতির মালিক", "en": "The Distresser"}', '{"bn": "ক্ষতি ও কষ্টও তাঁর অনুমতি ছাড়া আসে না, তাই তা দূর করতে কেবল তাঁর কাছেই চাইতে হয়; আন-নাফির সঙ্গে মিলিয়ে বলা উত্তম।", "en": "No harm comes except by His permission, so only He can remove it; best mentioned together with An-Nafi''."}', '{"bn": "সূরা ইউনুস ১০:১০৭", "en": "Yunus 10:107"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('7fb84727-b15f-5d6d-925b-d61be191f12d', 92, 'النَّافِعُ', '{"bn": "আন-নাফি", "en": "An-Nafi''"}', '{"bn": "কল্যাণদাতা", "en": "The Benefactor"}', '{"bn": "সব উপকার ও কল্যাণ তাঁর পক্ষ থেকেই আসে; তিনি উপকার করতে চাইলে কেউ বাধা দিতে পারে না।", "en": "All benefit comes from Him; if He intends benefit, none can prevent it."}', '{"bn": "সূরা ফাতহ ৪৮:১১", "en": "Al-Fath 48:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c140ff65-15f3-5e8f-b7f7-e76ff1b7f3c1', 93, 'النُّورُ', '{"bn": "আন-নূর", "en": "An-Nur"}', '{"bn": "জ্যোতি", "en": "The Light"}', '{"bn": "“আল্লাহ আসমান ও জমিনের নূর”; তিনিই হেদায়াতের আলো দান করেন।", "en": "“Allah is the Light of the heavens and the earth”; He grants the light of guidance."}', '{"bn": "সূরা নূর ২৪:৩৫", "en": "An-Nur 24:35"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('8a63bee1-5fb3-5671-8a56-67208ce19099', 94, 'الْهَادِي', '{"bn": "আল-হাদী", "en": "Al-Hadi"}', '{"bn": "পথপ্রদর্শক", "en": "The Guide"}', '{"bn": "যিনি সঠিক পথ দেখান; “পথপ্রদর্শক ও সাহায্যকারী হিসেবে তোমার রবই যথেষ্ট।”", "en": "He guides to the right path: “Sufficient is your Lord as a Guide and a Helper.”"}', '{"bn": "সূরা ফুরকান ২৫:৩১", "en": "Al-Furqan 25:31"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ffc39e48-9d0d-5182-9e9b-bcb0481a2428', 95, 'الْبَدِيعُ', '{"bn": "আল-বাদী", "en": "Al-Badi''"}', '{"bn": "অভিনব স্রষ্টা", "en": "The Incomparable Originator"}', '{"bn": "যিনি কোনো পূর্ব নমুনা ছাড়াই আসমান-জমিন সৃষ্টি করেছেন।", "en": "He created the heavens and the earth with no prior model."}', '{"bn": "সূরা বাকারা ২:১১৭", "en": "Al-Baqarah 2:117"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('9946d179-bb9f-5699-8203-a3754e35eedf', 96, 'الْبَاقِي', '{"bn": "আল-বাকী", "en": "Al-Baqi"}', '{"bn": "চিরস্থায়ী", "en": "The Everlasting"}', '{"bn": "সবকিছু ধ্বংস হবে, কেবল তিনিই বাকি থাকবেন; “আর বাকি থাকবে তোমার রবের চেহারা।”", "en": "Everything will perish and He alone will remain: “And there will remain the Face of your Lord.”"}', '{"bn": "সূরা আর-রহমান ৫৫:২৭", "en": "Ar-Rahman 55:27"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b72cb272-72cd-5cd8-a7ec-ffb994a9fe67', 97, 'الْوَارِثُ', '{"bn": "আল-ওয়ারিস", "en": "Al-Warith"}', '{"bn": "উত্তরাধিকারী", "en": "The Inheritor"}', '{"bn": "সবকিছু শেষ হলে সবকিছুর মালিকানা তাঁরই থাকবে; “আর আমিই চূড়ান্ত উত্তরাধিকারী।”", "en": "When all passes away, everything remains His: “And We are the Inheritor.”"}', '{"bn": "সূরা হিজর ১৫:২৩", "en": "Al-Hijr 15:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ba5d077b-5824-5827-920f-7c00d40845e6', 98, 'الرَّشِيدُ', '{"bn": "আর-রাশীদ", "en": "Ar-Rashid"}', '{"bn": "সঠিক পথে পরিচালনাকারী", "en": "The Guide to the Right Path"}', '{"bn": "যাঁর সব কাজ সঠিক ও কল্যাণকর এবং যিনি বান্দাকে সঠিক পথে চালান। এই নামটি এই রূপে কুরআনে আসেনি।", "en": "All His actions are right and good, and He directs His servants aright. This name does not occur in the Quran in this form."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e75a477f-1b03-5c81-8e62-dd0f5d9d155d', 99, 'الصَّبُورُ', '{"bn": "আস-সাবুর", "en": "As-Sabur"}', '{"bn": "পরম ধৈর্যশীল", "en": "The Most Patient"}', '{"bn": "বান্দাদের অবাধ্যতা দেখেও তিনি তাড়াহুড়া করে শাস্তি দেন না। সহিহ হাদিসে আছে, কষ্টদায়ক কথা শুনে আল্লাহর চেয়ে বেশি ধৈর্যশীল কেউ নেই (সহিহ বুখারি)।", "en": "He does not hasten to punish despite His servants'' disobedience. A sahih hadith says no one is more patient with hurtful words than Allah (Sahih al-Bukhari)."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
